INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(185, 'plPL', 'Łowy na tygrysy', 'Kiedy byłam jeszcze małą dziewczynką, ojciec uczył mnie sztuki polowania na tygrysy.$b$bMłode koty znacznie łatwiej wytropić i zabić. Dlatego zaczniemy od czegoś łatwego. Młode tygrysy często można znaleźć w pobliżu obozu ekspedycji.$b$bSprawdź swoje umiejętności tropienia i spróbuj upolować kilka tych bestii.', 'Ajeck Rouack z Ekspedycji Nesingwary\'ego chce, żebyś $gzabił:zabiła; 10 młodych tygrysów z Cierniodławów.', '', 'Wróć do Ajeck Rouack w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(186, 'plPL', 'Łowy na tygrysy', 'Robisz postępy, $N. Sprawdźmy teraz twoje umiejętności na dorosłych kotach. Tym razem zabij 10 tygrysów z Cierniodławów.', 'Ajeck Rouack z Ekspedycji Nesingwary\'ego chce, żebyś $gzabił:zabiła; 10 tygrysów z Cierniodławów.', '', 'Wróć do Ajeck Rouack w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(187, 'plPL', 'Łowy na tygrysy', 'Teraz podniosę stawkę i naprawdę sprawdzę twoje umiejętności. Udowodnij mi, że potrafisz zabić 10 starszych tygrysów z Cierniodławów. Jeśli ci się uda, będziesz $ggotów:gotowa; na ostatnią próbę, zanim w obecności mistrza Nesingwary\'ego ogłoszę cię $gmistrzem:mistrzynią; łowów na tygrysy.$b$bStarsze tygrysy z Cierniodławów nie tylko najtrudniej znaleźć – w walce są też najzacieklejsze.', 'Ajeck Rouack z Ekspedycji Nesingwary\'ego chce, żebyś $gzabił:zabiła; 10 starszych tygrysów z Cierniodławów.', '', 'Wróć do Ajeck Rouack w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(188, 'plPL', 'Łowy na tygrysy', 'Oto ostatnia próba, jaką ci wyznaczę. Od tygodni tropimy pewną nieuchwytną tygrysicę. Nazywamy tę bestię Sin\'Dall. Spróbuj dokonać tego, czego nie dokonał jeszcze nikt z twojej rasy: wytrop i zabij Sin\'Dall. Przynieś mi jej łapę jako dowód swojego wyczynu.$b$bWytropienie jej nie będzie łatwe.', 'Ajeck Rouack z Ekspedycji Nesingwary\'ego chce, żebyś $gzabił:zabiła; Sin\'Dall i $gwrócił:wróciła; z jej łapą.', '', 'Wróć do Ajeck Rouack w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(189, 'plPL', 'Uszy Krwawych Skalpów', 'Przeklęte trolle! Wybijają naszych agentów w dżungli! Straciłem już sporo najlepszych strażników w potyczkach z nimi. Koszty rosną! Jak ja to wytłumaczę baronowi Revilgazowi?$b$bZdecydowane działanie... Myśl, Kebok... nie dostałeś tego stanowiska za siedzenie z założonymi rękami... Mam! Ty... $n, tak? Pomożesz mi, prawda? Można na tym zarobić!$b$bUmowa jest taka... przyniesiesz mi uszy piętnastu trolli z Krwawych Skalpów, a ja sowicie cię wynagrodzę.', 'Zdobądź 15 uszu Krwawych Skalpów i zanieś je Kebokowi w Łupieżczej Zatoce.', '', 'Wróć do Keboka w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(190, 'plPL', 'Łowy na pantery', 'Jeśli chcesz polować z tą wyborową drużyną pod wodzą Hemeta juniora, musisz udowodnić, że umiesz polować na pantery. Zaczniemy od czegoś łatwego, nie martw się. Na początek zabij 10 młodych panter.$b$bWytropienie ich to dopiero połowa wyzwania...', 'Sir S. J. Erlgadin z Ekspedycji Nesingwary\'ego chce, żebyś $gzabił:zabiła; 10 młodych panter.', '', 'Wróć do sira S. J. Erlgadina w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(191, 'plPL', 'Łowy na pantery', 'Teraz możesz wejść poziom wyżej. Jeśli chcesz udowodnić, że jesteś $ggodzien:godna; obracać się w towarzystwie takich łowców grubej zwierzyny, musisz pokazać, że potrafisz zabić 10 panter.$b$bTe duże są twardsze. Nie pójdzie ci z nimi tak łatwo jak z młodymi, które $gzabijałeś:zabijałaś; wcześniej.', 'Sir S. J. Erlgadin z Ekspedycji Nesingwary\'ego chce, żebyś $gzabił:zabiła; 10 panter.', '', 'Wróć do sira S. J. Erlgadina w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(192, 'plPL', 'Łowy na pantery', 'Teraz najtrudniejsza część. Prawdziwy łowca panter wykazuje się, powalając pantery cienistozębne, najgroźniejsze w Cierniodławach. Udowodnij nam, że potrafisz zabić 10 tych bestii.$b$bJeśli myślisz, że trudno je wytropić, poczekaj, aż spróbujesz którąś zabić...', 'Sir S. J. Erlgadin z Ekspedycji Nesingwary\'ego chce, żebyś $gzabił:zabiła; 10 panter cienistozębnych.', '', 'Wróć do sira S. J. Erlgadina w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(193, 'plPL', 'Łowy na pantery', '$GUdowodniłeś:Udowodniłaś; już prawie, że jesteś $gmistrzem:mistrzynią; łowów na pantery. Po dżungli grasuje pantera zwana Bhag\'therą. Jak dotąd wymyka się naszej drużynie. Sprawdź, czy twoje umiejętności wystarczą, by zabić wielkiego Bhag\'therę.$b$bPrzynieś mi Kieł Bhag\'thery, a zdobędziesz mój szacunek!', 'Sir S. J. Erlgadin z Ekspedycji Nesingwary\'ego chce, żebyś $gprzyniósł:przyniosła; mu Kieł Bhag\'thery.', '', 'Wróć do sira S. J. Erlgadina w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(194, 'plPL', 'Łowy na raptory', 'Więc myślisz, że twoje umiejętności łowieckie są w szczytowej formie? Sprawdzę to w mgnieniu oka. Ruszaj do dżungli i zabij 10 raptorów z Cierniodławów. Zobaczymy, $gjakim:jaką; z ciebie $głowcą:łowczynią; grubej zwierzyny.$b$bI nie, nie powiem ci, gdzie ich szukać! Odnalezienie bestii to połowa wyzwania.', 'Hemet Nesingwary junior chce, żebyś $gzabił:zabiła; 10 raptorów z Cierniodławów.', '', 'Wróć do Hemeta Nesingwary\'ego juniora w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(195, 'plPL', 'Łowy na raptory', 'Podnieśmy teraz poprzeczkę i zobaczmy, czy sobie poradzisz. Wyrusz do dżungli i ustrzel 10 tych przeklętych raptorów biczoogonów. Pokaż, na co cię stać!', 'Hemet Nesingwary junior chce, żebyś $gzabił:zabiła; 10 raptorów biczoogonów.', '', 'Wróć do Hemeta Nesingwary\'ego juniora w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(196, 'plPL', 'Łowy na raptory', 'Zobaczmy, jak poradzisz sobie z kolejnym wyzwaniem. Żyje tu pewien przebiegły gatunek raptorów. Nazywamy je dżunglowymi czyhaczami. Znacznie trudniej je wytropić i zabić niż inne gatunki, na których $gpróbowałeś:próbowałaś; szczęścia. Zabij 10 dżunglowych czyhaczy, a zdradzę ci, gdzie są najlepsze łowy.', 'Hemet Nesingwary junior chce, żebyś $gzabił:zabiła; 10 dżunglowych czyhaczy.', '', 'Wróć do Hemeta Nesingwary\'ego juniora w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(197, 'plPL', 'Łowy na raptory', 'Skoro $gokazałeś:okazałaś; się w dżungli tak $grzutki:rzutka;, opowiem ci o dzikim raptorze, którego nawet mnie nie udało się zabić. Ajeck nazywa tego przebiegłego raptora Tethisem.$b$bJeśli chcesz udowodnić, że jesteś $gprawdziwym mistrzem:prawdziwą mistrzynią;, zabij Tethisa i przynieś mi jego szpon. Byłby to wyczyn, jakiego nie dokonał jeszcze żaden łowca grubej zwierzyny.', 'Hemet Nesingwary junior chce, żebyś $gzabił:zabiła; Tethisa, nieuchwytnego i groźnego raptora z Cierniodławów.', '', 'Wróć do Hemeta Nesingwary\'ego juniora w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(198, 'plPL', 'Zaopatrzenie dla szeregowego Thorsena', 'Hmm. Tak, właściwie mam coś, czym możesz się zająć. Porucznik Doren i jego ludzie na północy potrzebują od nas regularnych dostaw.$b$bNie zostały dostarczone, a skoro trolle atakują, potrzebuję kogoś, kto to zrobi. Obóz Dorena leży na północny zachód od drogi, przy wejściu do Cierniodławów od strony Kniei Zmierzchu. Oddaj zaopatrzenie szeregowemu Thorsenowi; jeśli nie będzie go w obozie, znaczy, że patroluje teren na południe od niego. On się tym zajmie.$b$bTylko pamiętaj: jeśli zawiedziesz, będziesz mi $gwinien:winna; odszkodowanie.', 'Dostarcz różne zaopatrzenie goblinów szeregowemu Thorsenowi.', '', 'Zamelduj się u szeregowego Thorsena w Dolinie Cierniodławów.', '', '', '', '', 0),
(200, 'plPL', 'Bukmacher Herod', 'Jeśli Kurzen zna sekret Thorsena, to mamy wśród nas szpiega. Musimy ustalić, jak doszło do przecieku!$B$BKontaktem Thorsena w obozie Kurzena był bukmacher Herod. Herod jest kwatermistrzem Kurzena i wie wszystko o funkcjonowaniu Siedliska Kurzena. Jeśli zdobędziesz notatki lub zapiski Heroda, może dowiemy się, jak Thorsen został zdemaskowany.$B$BGdy byliśmy jeszcze z Kurzenem, biuro bukmachera mieściło się na piętrze jedynego piętrowego domu w obozie. Jego zapiski pewnie wciąż tam są.', 'Znajdź zapiski bukmachera Heroda.', '', 'Znajdź zapiski bukmachera Heroda w Dolinie Cierniodławów.', '', '', '', '', 0),
(201, 'plPL', 'Zbadaj obóz', 'Dotarły do mnie wieści o grupie myśliwych, którzy rozbili obóz w górę rzeki od obozu górniczego spółki Gitgeszeft nad Jeziorem Nazferiti. Normalnie by mnie to nie obchodziło, ale – o dziwo – słyszałem, że jednym z tych myśliwych jest Hemet Nesingwary junior. Ma znakomite koneksje, jeśli rozumiesz, co mam na myśli, a ostrożności nigdy za wiele.$b$bMoże zajrzysz do tego obozu, $n, i sprawdzisz, co knują?', 'Znajdź obóz myśliwych i przekaż jego położenie Krazekowi w Łupieżczej Zatoce.', 'Odnajdź obóz myśliwych', 'Wróć do Krazeka w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(202, 'plPL', 'Pułkownik Kurzen', 'Raz po raz dowodzisz swojej wartości, a twoja zaradność zdaje się dorównywać nawet zaradności samego Kurzena. Możesz okazać się zbawieniem naszej garstki buntowników... jeśli zmierzysz się z Kurzenem i zwyciężysz!$B$BKurzen dowodzi swoimi ludźmi z głębi Składowiska. Musisz wejść do tej jaskini, przebić się przez jego obrońców i stawić czoła Kurzenowi i jego dowódcom.$B$BŻegnaj, $N. Moja nadzieja i los moich ludzi idą z tobą.', 'Zabij 6 elitarnych żołnierzy Kurzena i 4 podwodzów Kurzena, a następnie przynieś głowę Kurzena porucznikowi Dorenowi w Obozie Buntowników.', '', 'Wróć do porucznika Dorena w Obozie Buntowników w Dolinie Cierniodławów.', '', '', '', '', 0),
(203, 'plPL', 'Druga rebelia', 'Przegrywamy walkę z pułkownikiem Kurzenem. Nie dość, że to genialny taktyk, to ma nad nami co najmniej dziesięciokrotną przewagę! Żeby przetrwać, musimy użyć przeciwko niemu jego własnej taktyki skrytych ataków.$B$BWejdź do jego obozu na wschodzie i zabijaj jego ludzi. Mnóstwo ludzi. I wynoś się stamtąd, zanim zdążą cię osaczyć posiłki.', 'Zabij 15 dżunglowych bojowników Kurzena.$B$BWróć do sierżant Yohwy w Obozie Buntowników.', '', 'Wróć do sierżant Yohwy w Obozie Buntowników w Dolinie Cierniodławów.', '', '', '', '', 0),
(204, 'plPL', 'Złe lekarstwa', 'Żeby mieć szansę z Kurzenem, musimy odciąć go od wsparcia uzdrowicieli. Zebrał wielu uzdrowicieli, którzy leczą jego oddziały lekarstwami z dżungli, a naszych bojowników trują wyciągiem z jadowitej paproci.$B$BPotrzebujemy tych lekarstw i wyciągów dla siebie. Przeszukaj Siedlisko Kurzena – jego uzdrowiciele i dżunglowi bojownicy będą mieli lekarstwa, a wyciągi są pewnie schowane w skrzyniach z zapasami w obozie.', 'Przynieś 7 lekarstw z dżungli i 1 wyciąg z jadowitej paproci sierżant Yohwie w Obozie Buntowników.', '', 'Wróć do sierżant Yohwy w Obozie Buntowników w Dolinie Cierniodławów.', '', '', '', '', 0),
(205, 'plPL', 'Trollowe czary', 'Kiedy będę studiował legendy, które $gzdobyłeś:zdobyłaś;, zbierz dla mnie narzędzia złej trollowej magii. Wkrocz na terytorium trolli z Rozłupywaczy Czaszek, drugiego plemienia daleko na południu, i zdobądź fetysze Rozłupywaczy Czaszek od ich znachorów i mistyków.', 'Przynieś 4 fetysze Rozłupywaczy Czaszek bratu Nimetzowi w Obozie Buntowników.', '', 'Wróć do brata Nimetza w Obozie Buntowników w Dolinie Cierniodławów.', '', '', '', '', 0),
(206, 'plPL', 'Mai\'Zoth', 'Kurzen może i nie żyje, ale... to, co pchnęło go ku złu, wciąż żyje! Dzięki moim badaniom odkryłem, że ogrzy mag, Mai\'Zoth, mieszka w ogrzym kopcu we wschodnich górach Cierniodławów. Podobno włada magią zniewalającą umysły i jestem pewien, że to on zdeprawował Kurzena.$B$BJeśli Mai\'Zoth pozostanie przy życiu, jego zło może opanować innych, a nawet sprawić, że pojawi się kolejny Kurzen.$B$BZabij go i przynieś mi jego Oko umysłu, artefakt, którym deprawuje innych.', 'Przynieś Oko umysłu bratu Nimetzowi w Obozie Buntowników.', '', 'Wróć do brata Nimetza w Obozie Buntowników w Dolinie Cierniodławów.', '', '', '', '', 0),
(207, 'plPL', 'Tajemnica Kurzena', 'Pułkownik Kurzen był niegdyś wielkim, szlachetnym człowiekiem – muszę się dowiedzieć, co sprawiło, że upadł tak nisko! Być może jest pod wpływem trollowej magii. Żeby to potwierdzić, muszę zbadać niektóre z ich legend.$B$BW trollowych ruinach Cierniodławów ukryto 4 tablice. Muszę zobaczyć, co na nich napisano! Przepisz ich znaki i przynieś mi odpisy.$B$BPierwsza tablica jest w Ruinach Bal\'lal, druga przy Plugawej Rafie, a trzecia i czwarta w Ruinach Zul\'Kunda.', 'Znajdź 4 tablice i przynieś ich legendy bratu Nimetzowi.', '', 'Wróć do brata Nimetza w Obozie Buntowników w Dolinie Cierniodławów.', '', '', '', '', 0),
(208, 'plPL', 'Łowca grubej zwierzyny', '$N, jesteś $głowcą godnym:łowczynią godną; naszego towarzystwa. Od pól bitewnych Lordaeronu po najgłębszą dżunglę rzadko widywałem taką biegłość we władaniu bronią, jaką $gwykazałeś:wykazałaś;.$b$b$GZabiłeś:Zabiłaś; dziką Sin\'Dall, nieuchwytnego Bhag\'therę i zdradliwego Tethisa. Ale prawdziwą zdobyczą jest głowa króla Bangalasha. To z powodu tego białego tygrysa tu jestem. Mam go na muszce od dłuższego czasu. Zabij króla Bangalasha, a udowodnisz, że w łowach nie masz sobie równych.', 'Hemet Nesingwary junior chce, żebyś $gprzyniósł:przyniosła; mu głowę króla Bangalasha, wielkiego białego tygrysa.', '', 'Wróć do Hemeta Nesingwary\'ego juniora w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(209, 'plPL', 'Kły Rozłupywaczy Czaszek', 'Zabijanie tylu tygrysów, żeby utrzymać eksport tygrysich kłów na wyspy Południowych Mórz, jest drogie i trudne. Na szczęście opracowaliśmy technikę, dzięki której zwykłe rogopodobne przedmioty zmieniamy w nie do wykrycia podróbki.$b$bNajlepiej pasują, co zdumiewające, kły trolli z Rozłupywaczy Czaszek.$b$bEj, zanim cokolwiek powiesz: czego kupujący nie wie, to mu nie zaszkodzi, prawda? Przynieś mi ich sporo, żebyśmy mogli zabrać się do comiesięcznej dostawy!', 'Zdobądź 18 kłów Rozłupywaczy Czaszek i zanieś je Kebokowi.', '', 'Wróć do Keboka w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(210, 'plPL', 'Kuchnia Krazeka', 'Gotuję w obozie większość posiłków. Kiedyś było przy tym mnóstwo roboty, dopóki nie kupiłem mechanicznego garnka od goblińskiego kupca z Łupieżczej Zatoki. Ten garnek to cud! Zaoszczędził mi niezliczonych godzin... dopóki się nie zepsuł!$B$BMożesz zanieść go temu goblinowi, żeby go naprawił? Nazywa się Krazek.', 'Zanieś wolnowar Krazeka goblinowi Krazekowi.', '', 'Zamelduj się u Krazeka w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(213, 'plPL', 'Wrogie przejęcie', 'Tym razem przesadził! Mało, że Gelriz wypycha magnatów wyznaczonych przez kupieckich książąt, to jeszcze próbuje wejść w paradę najsłynniejszemu piratowi!$b$bRevilgaz na to nie pozwoli i kazał mi rozwiązać ten problem po swojemu.$b$bPo mojemu? Kradzież. Geolodzy spółki Gitgeszeft nad Jeziorem Nazferiti bardzo się interesują dziwnymi niebieskimi kryształami, które znajdują w kopalniach. Przynieś mi próbki tego kamienia od ich geologów. Nie obchodzi mnie, co będziesz $gmusiał:musiała; zrobić, żeby je zdobyć.', 'Zdobądź 8 wygładzonych kryształów i zanieś je Kebokowi w Łupieżczej Zatoce.', '', 'Wróć do Keboka w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(215, 'plPL', 'Tajemnice dżungli', 'Dziękuję, że mnie $gocaliłeś:ocaliłaś;, $N. Wiem, jak to wygląda, ale... pozwól mi wyjaśnić.$B$BPorucznik Doren polecił mi ponownie zaciągnąć się do ludzi Kurzena, żebym mógł ich szpiegować i dostarczać buntownikom tak bardzo potrzebne informacje. To, co tu $gwidziałeś:widziałaś;, miało być moją szansą na przeniknięcie do Siedliska Kurzena. Myliłem się i jeszcze raz dziękuję za ratunek.$B$BTo była ściśle tajna misja, więc nie możesz nikomu o niej mówić. Ale jeśli porozmawiasz z Dorenem, on ci wszystko wyjaśni.', 'Porozmawiaj z porucznikiem Dorenem w Obozie Buntowników.', '', 'Porozmawiaj z porucznikiem Dorenem w Obozie Buntowników w Dolinie Cierniodławów.', '', '', '', '', 0),
(328, 'plPL', 'Ukryty klucz', 'Choć w tych zapiskach nie ma żadnej wzmianki o szeregowym Thorsenie, w oprawie jednej z ksiąg rachunkowych Heroda ukryto mały mosiężny klucz.$B$BPo dokładniejszym przejrzeniu notatek wśród rozmaitych papierów znajdujesz kilka wzmianek o „bezpiecznej kasetce”. Kasetka jest gdzieś na Składowisku – w kompleksie jaskiń na tyłach Siedliska Kurzena.$B$BJeśli uda się odnaleźć tę kasetkę, a mały mosiężny klucz ją otworzy, być może wyjaśni się, jak zdemaskowano Thorsena.', 'Użyj małego mosiężnego klucza, by otworzyć kasetkę bukmachera Heroda.', '', 'Wróć do kasetki bukmachera Heroda w Dolinie Cierniodławów.', '', '', '', '', 0),
(329, 'plPL', 'Szpieg zdemaskowany!', 'Wśród kosztowności w kasetce leży zabłocony, nabazgrany liścik. Choć ledwo czytelny, wygląda na rozkład dnia szeregowego Thorsena. Opisuje trasy jego patroli, z kim rozmawia i jak spędza czas wśród buntowników. Podpisano go tylko jedną literą: -M.$B$BKtokolwiek napisał ten liścik, musiał przebywać bardzo blisko Thorsena. Autor tego liściku jest zdrajcą w obozie buntowników.', 'Zanieś zabłocony liścik porucznikowi Dorenowi w Obozie Buntowników.', '', 'Zamelduj się u porucznika Dorena w Obozie Buntowników w Dolinie Cierniodławów.', '', '', '', '', 0),
(330, 'plPL', 'Grafik patroli', 'Liścik, który mi $gdałeś:dałaś;, jest podpisany „-M”... Nie wiem, co to może znaczyć.$B$BAle... z liściku wynika też, że ta osoba patrolowała z Thorsenem w zeszłym tygodniu. Więc ten, kto w zeszłym tygodniu chodził z Thorsenem na patrol, musi być zdrajcą!$B$BIdź do kaprala Sethmana. On układa grafik patroli i powie ci, kto był z Thorsenem.', 'Porozmawiaj z kapralem Sethmanem.', '', 'Porozmawiaj z kapralem Sethmanem w Obozie Buntowników w Dolinie Cierniodławów.', '', '', '', '', 0),
(331, 'plPL', 'Raport dla Dorena', 'Czy porucznik Doren chciał, żebyś $gwrócił:wróciła; do niego z tą informacją o patrolach?', 'Porozmawiaj z porucznikiem Dorenem.', '', 'Porozmawiaj z porucznikiem Dorenem w Obozie Buntowników w Dolinie Cierniodławów.', '', '', '', '', 0),
(338, 'plPL', 'Zielone wzgórza Cierniodławów', 'Mistrz Nesingwary strasznie się zdenerwuje, jeśli się dowie!$b$bPowierzył mi korektę rękopisu swojej powieści „Zielone wzgórza Cierniodławów”. Wszystko szło dobrze, ale przez obóz przeleciał silny podmuch wiatru i rozwiał kartki po całej okolicy!$b$bUdało mi się zebrać większość stron, ale wiele wciąż leży porozrzucanych po dżungli. Zbierz strony, żeby skompletować każdy z czterech rozdziałów.$b$bPomogę ci je uporządkować. Wróć do mnie z rozdziałami, gdy będziesz mieć wszystkie cztery.', 'Zbierz brakujące strony rękopisu „Zielonych wzgórz Cierniodławów”. Gdy wszystkie cztery rozdziały będą kompletne, zanieś je Barnilowi.', '', 'Wróć do Barnila Kamiennego Garnka w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(339, 'plPL', 'Rozdział I', 'Rozdział I był naprawdę pasjonujący! Mistrz Nesingwary nakreśla w nim tło opowieści i wspomina swoich towarzyszy łowów, w tym mnie!$b$bAle nie o to chodzi. Zobaczmy, których stron wciąż brakuje. Wygląda na to, że strony 1, 4, 6 i 8 są jeszcze gdzieś w dżungli!', 'Przynieś strony 1, 4, 6 i 8 „Zielonych wzgórz Cierniodławów” Nesingwary\'ego Barnilowi Kamiennemu Garnkowi, by skompletować rozdział I.', '', 'Wróć do Barnila Kamiennego Garnka w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(340, 'plPL', 'Rozdział II', 'Rozdział II był pełen ekscytujących opowieści o polowaniach na pantery i tygrysy. Mógłbym sobie w brodę pluć, że pozwoliłem wiatrowi porwać te strony!$b$bWygląda na to, że udało mi się odzyskać wszystkie strony oprócz 10, 11, 14 i 16.', 'Przynieś strony 10, 11, 14 i 16 „Zielonych wzgórz Cierniodławów” Nesingwary\'ego Barnilowi Kamiennemu Garnkowi, by skompletować rozdział II.', '', 'Wróć do Barnila Kamiennego Garnka w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(341, 'plPL', 'Rozdział III', 'Rozdział III był moim ulubionym. Opowiada o pierwszej zdobyczy sira Erlgadina i lady Rouack upolowanej z krasnoludzkiej strzelby. A zakończenie rozdziału III – cóż za trzymający w napięciu moment!$b$bWygląda na to, że do dokończenia rozdziału wciąż potrzebujemy stron 18, 20, 21 i 24. Gdzieś tam na nas czekają...', 'Przynieś strony 18, 20, 21 i 24 „Zielonych wzgórz Cierniodławów” Nesingwary\'ego Barnilowi Kamiennemu Garnkowi, by skompletować rozdział III.', '', 'Wróć do Barnila Kamiennego Garnka w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(342, 'plPL', 'Rozdział IV', 'Ach, rozdział IV – wielki finał! I co to było za zakończenie!$b$bW tym rozdziale brakuje nam tylko trzech stron. Potrzebujemy stron 25, 26 i 27, żeby złożyć rozdział IV z powrotem.', 'Przynieś strony 25, 26 i 27 „Zielonych wzgórz Cierniodławów” Nesingwary\'ego Barnilowi Kamiennemu Garnkowi, by skompletować rozdział IV.', '', 'Wróć do Barnila Kamiennego Garnka w obozie Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(348, 'plPL', 'Gorączka Cierniodławów', 'Chory... tak... bardzo ch-ch-chory...$b$b...złapałem gorączkę Cierniodławów... zabójczy w-w-wirus...$b$b...jedyne lekarstwo... to... to... zjeść serce M-m-m-m-mokka Dzikiego... nieuchwytnej białej bestii...$b$b...znachor Unbagwa... jedyny, który może go p-p-przywołać...$b$b...szukaj Unbagwy w ukrytej jaskini na południowym przylądku...$b$b...pośpiesz się... umieram... umieram...', 'Odszukaj znachora Unbagwę i poproś go, żeby przywołał Mokka Dzikiego. Przynieś serce Mokka Finowi Fizracketowi.', '', 'Wróć do Fina Fizracketa w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(349, 'plPL', 'Gorączka Cierniodławów', 'Ty chcieć serce Mokka Dzikiego? Znachor Unbagwa wiedzieć, jak go zwabić. Tak, tak!$b$bJa gadać z duchami i Mokk przyjść. Ale najpierw ty przynieść kieł goryla. Bez kła duchy nie słuchać.$b$bI ty uważać: inne goryle-bestie też słyszeć gadanie z duchami. One przyjść pierwsze. Ty chronić znachora Unbagwę!', 'Przynieś kieł goryla znachorowi Unbagwie w Dolinie Cierniodławów i chroń go, gdy będzie przywoływał Mokka Dzikiego.', '', 'Wróć do znachora Unbagwy w Dolinie Cierniodławów.', '', '', '', '', 0),
(568, 'plPL', 'Obrona Grom\'gol', 'Throm\'ka, $N!$b$bTwoje przybycie do Grom\'gol jest doprawdy w porę. Jako dowódca obozu wodza tutaj, w dżungli, jestem zobowiązany honorem dbać o bezpieczeństwo wszystkich członków Hordy. Naszą misję zapewnienia bezpiecznego szlaku zaopatrzenia do Stonardu utrudniają niektórzy miejscowi mieszkańcy.$b$bPowierzam ci przetrzebienie raptorów w okolicach Grom\'gol. Gdy poczynisz znaczne postępy, wróć do mnie po nowy przydział.', 'Dowódca Aggro\'gosh z Obozu Grom\'gol chce, żebyś $gzabił:zabiła; 15 raptorów biczoogonów.', '', 'Wróć do dowódcy Aggro\'gosha w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(569, 'plPL', 'Obrona Grom\'gol', 'Gdy przybyliśmy do tej dżungli, nie zamierzaliśmy wypowiadać wojny miejscowym plemionom. Nasza misja zaopatrywania Stonardu ma najwyższy priorytet. Pojawiły się jednak komplikacje. Miejscowa banda ogrów zajęła Ruiny Mizjah na południowy wschód od Grom\'gol. Mimo ostrzeżeń wciąż napadają na nasze karawany z zaopatrzeniem.$b$bPowierzam ci rozprawienie się z tymi opornymi ogrami.$b$bUdaj się do ruin i spróbuj przepędzić ich z okolicy. W najgorszym razie będzie to dla nich stanowcze ostrzeżenie.', 'Dowódca Aggro\'gosh z Obozu Grom\'gol chce, żebyś $gzabił:zabiła; 10 osiłków Mosh\'Ogg i 5 znachorów Mosh\'Ogg.', '', 'Wróć do dowódcy Aggro\'gosha w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(570, 'plPL', 'Zaklęcie Mok\'thardina', 'Moc magii dżungli trzeba poznać, a potem ujarzmić dla Hordy. Moje rytuały jak dotąd się powiodły. Potrafię rzucać bardzo potężne zaklęcia. Dla ciebie, $gdzielny wojowniku:dzielna wojowniczko;, wykonam naprawdę wyjątkowy przedmiot.$b$bPrzynieś mi kilka pazurów panter cienistozębnych i kieł tygrysicy. Nie byle jaki kieł – musi być w nieskazitelnym stanie.$b$bBestie czają się w całej dżungli, ale kilka znajdziesz niedaleko stąd, zaraz za rzeką od Ruin Mizjah, na południowym wschodzie.', 'Wieszcz Mok\'thardin z Obozu Grom\'gol chce dostać 8 pazurów pantery cienistozębnej i nieskazitelny kieł tygrysicy.', '', 'Wróć do wieszcza Mok\'thardina w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(571, 'plPL', 'Zaklęcie Mok\'thardina', 'To, czego teraz od ciebie potrzebuję, będzie bardzo trudno zdobyć.$b$bŻeby utrzymać te wszystkie pióra, pazury i nieskazitelny kieł na miejscu, potrzebuję magicznego wiązania. Nada się tylko stare ścięgno goryla.$b$bZnajdziesz je jedynie u starszych goryli z Mglistej Doliny. Podobno żerują na wschód od Łupieżczej Zatoki.$b$bŚcięgno musi być doskonałe. Być może trzeba będzie zabić sporo goryli, zanim znajdziesz dokładnie to, czego potrzebuję, ale te łowy będą tego warte.', 'Przynieś stare ścięgno goryla wieszczowi Mok\'thardinowi w Grom\'gol.', '', 'Wróć do wieszcza Mok\'thardina w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(572, 'plPL', 'Zaklęcie Mok\'thardina', 'Przedmioty, które $gzebrałeś:zebrałaś; z kocich bestii Doliny, to dopiero pierwszy składnik potężnego zaczarowanego przedmiotu. Te dżunglowe błyskotki w połączeniu z moim szamańskim rytuałem dadzą ci bardzo przydatne narzędzie w służbie Hordy i wodza.$b$bTeraz jednak musisz zebrać dla mnie pióra dżunglowych czyhaczy. Bestie te tradycyjnie noszą pióra na opaskach na ramionach. Plemię tych raptorów znajdziesz na południe od Grom\'gol, niedaleko wielkiej areny.', 'Przynieś 10 piór dżunglowego czyhacza wieszczowi Mok\'thardinowi w Obozie Grom\'gol.', '', 'Wróć do wieszcza Mok\'thardina w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(573, 'plPL', 'Zaklęcie Mok\'thardina', 'Do dokończenia zaklęcia potrzebny jest jeszcze tylko jeden odczynnik.$b$bNa południu, w stronę zachodniego wybrzeża, wysoko ponad urwiskami, leży Święte Źródło. Źródło to jest przedmiotem wielkiego sporu wśród uczonych religijnych i mistycznych. Każda rasa Azeroth twierdzi, że jego wody zostały uświęcone dla jej ludu.$b$bMoja ostatnia prośba: przynieś mi świętą wodę źródlaną. Ale uważaj. Wyprawa nag odkrywców podeszła pod źródło. Z nimi też trzeba będzie się rozprawić.', 'Wieszcz Mok\'thardin z Grom\'gol potrzebuje świętej wody źródlanej. Chce też, żebyś $gzabił:zabiła; 10 nag odkrywców.', '', 'Wróć do wieszcza Mok\'thardina w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(574, 'plPL', 'Siły specjalne', 'Teraz, gdy wielu jego zwykłych żołnierzy padło, musisz zmierzyć się z jego doborowymi oddziałami. Gdy nie wyrzynają naszych buntowników w dziczy, przebywają w głębi Siedliska Kurzena, w jaskini zwanej Składowiskiem.$B$BZnam osobiście wielu żołnierzy Kurzena i wiem, że są wprawni, lojalni i okrutni. Niełatwe zadanie ci wyznaczam, $N.$B$BGdy ich pokonasz, zamelduj się u porucznika Dorena, mojego dowódcy. Będzie chciał usłyszeć raport z pierwszej ręki.', 'Zabij 10 komandosów Kurzena i 6 kurczygłowów Kurzena.$B$BZamelduj się u porucznika Dorena w Obozie Buntowników.', '', 'Wróć do porucznika Dorena w Obozie Buntowników w Dolinie Cierniodławów.', '', '', '', '', 0),
(575, 'plPL', 'Podaż i popyt', '„Najlepszy kaletnik Południowych Mórz oraz światów starego i nowego”. Tak na mnie mówią. Na mnie! Na Drizzlika! Najlepszy kal... Ehem. No cóż.$b$bMoje wyroby skórzane słyną wszędzie jako najwykwintniejsze, wybór koneserów!$b$bWłaśnie dostałem od dyrektora Riddlevoxa ze Związku Majsterkowiczów zamówienie na tuzin Wzniosłych butów, jego ulubionego modelu. To zresztą nasz największy przebój.$b$bŻeby zacząć od podstawowego kształtu, będę potrzebował skór krokoliszków znad rzeki w północnych Cierniodławach.', 'Przynieś 2 duże skóry rzecznego krokoliszka Drizzlikowi w Łupieżczej Zatoce.', '', 'Wróć do Drizzlika w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(576, 'plPL', 'Miej oko na oko', 'Stać! Kto idzie?$b$bArgh, bez mojego specjalnego zaczarowanego oka jestem do niczego. Dość już, żem w ogóle stracił oczy w bitwie! Ale jakimś szczęśliwym trafem zawinęliśmy do Menethil, a wędrowny czarodziej zaczarował dla mnie specjalne szklane oko, dzięki któremu znów widzę.$b$bZeszłej nocy, gdym wychodził, napadli mnie jacyś piraci z Krwawych Żagli. Zabrali mi oko, zabrali! Wygląda na to, że te łotry trafiły aż do Łupieżczej Zatoki.$b$bPomożesz staremu wilkowi morskiemu odzyskać oko?', 'Zakręcony Jednooki z Łupieżczej Zatoki chce, żebyś $godzyskał:odzyskała; jego oko od piratów z Krwawych Żagli.', '', 'Wróć do Zakręconego Jednookiego w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(577, 'plPL', 'Wymaga częściowego montażu', 'No więc ogólny kształt butów już mam i robota idzie dobrze, ale skóry, które $gprzyniosłeś:przyniosłaś;, nie wystarczą na wewnętrzne warstwy.$b$b„Co teraz zrobimy, Drizzliku?” – to pytanie masz pewnie na końcu języka. No i całe szczęście, że rozmawiasz z Drizzlikiem, bo on ci zaraz powie, co zrobimy!$b$bWewnętrznych warstw i tak nikt nigdy nie zobaczy, więc wypchamy buty grubszymi, tańszymi skórami krokoliszków znad Jeziora Nazferiti.', 'Przynieś 5 skór krokoliszka kłapacza Drizzlikowi w Łupieżczej Zatoce.', '', 'Wróć do Drizzlika w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(578, 'plPL', 'Kamień Pływów', 'Jeśli na tej wyspie naprawdę straszą gobliński mag i żywiołaki wody, to może Kamień Pływów będzie mój!$b$bChcę, żebyś $godnalazł:odnalazła; tę nawiedzoną wyspę... i $gsprawdził:sprawdziła;, co się tam dzieje. A, i jeśli chcesz dowiedzieć się czegoś więcej o Kamieniu Pływów, zanieś to pismo do biblioteki w Wichrogrodzie. Powinni znaleźć dla ciebie egzemplarz księgi, w której po raz pierwszy natrafiłem na tę legendę.$b$bCzyżby Gazban naprawdę odkrył Kamień...?', 'Odnajdź nawiedzoną wyspę dla barona Revilgaza z Łupieżczej Zatoki.', 'Odnajdź nawiedzoną wyspę', 'Wróć do barona Revilgaza w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(580, 'plPL', 'Zgubiony grog Chudego Whiskeya', 'Ostro popijaliśmy przy Urwiskach Widokowych, a w oddali majaczyło stare Zaziemie. Myślałem, że morze połknie nas w całości.$b$bStary Chudy wie wszystko o odwadze z butelki! Kapitan miał skrzynkę porto Pupellyverbos, którą zarekwirowaliśmy kaprowi płynącemu do Wichrogrodu.$b$bKiedy więc przy Zaziemiu dopadł nas sztorm, dobrałem się do grogu. Przyszła wielka fala i zmyła butelki za burtę. Kapitan przetrzepie mi skórę kotem o dziewięciu ogonach, jeśli nie pomożesz mi ich odzyskać!', 'Chudy Whiskey z Łupieżczej Zatoki chce, żebyś $gprzyniósł:przyniosła; mu zgubione butelki porto Pupellyverbos.', '', 'Wróć do Chudego Whiskeya w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(581, 'plPL', 'Poszukiwania Yenniku', 'Zguba, oto co jest. Zguba ciąży na najmłodszym synu mojego wodza, Yenniku. Zgodnie ze zwyczajem naszego ludu oddano go trollom Gurubaszów z Zul\'Gurub, lecz gdy moje plemię, plemię Mrocznej Włóczni, odeszło z orkiem Thrallem, biedny Yenniku przepadł dla nas. Wysłano mnie z dalekiego Orgrimmaru z powrotem do Cierniodławów, abym odszukał syna mojego wodza.$B$BWierzę, że ma go plemię Krwawych Skalpów.$B$BJeśli chcesz mi pomóc, poluj na Krwawe Skalpy. Znajdziesz ich na północy. Zbierz ich kły i wróć do mnie.', 'Przynieś 9 kłów Krwawych Skalpów Nimboyi w Obozie Grom\'gol.', '', 'Wróć do Nimboyi w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(582, 'plPL', 'Łowy na głowy', 'Musimy się dowiedzieć, czy Yenniku nie żyje.$B$BZabijaj łowców głów Krwawych Skalpów i odbieraj im skurczone głowy. Musisz zebrać wiele, bardzo wiele głów, a ja je obejrzę, by się upewnić, że nie ma wśród nich głowy Yenniku.$B$BA jeśli Yenniku zginął z rąk Krwawych Skalpów, niech na ducha ich wodza, Gan\'zulaha, spadnie klątwa na sześćset lat!$B$BIdź, $N. Wielu łowców głów znajdziesz w ruinach Zuuldaia i Zul\'Kunda, wzdłuż wybrzeża na północy.', 'Przynieś 20 skurczonych głów Nimboyi w Obozie Grom\'gol.', '', 'Wróć do Nimboyi w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(583, 'plPL', 'Witaj w dżungli', 'Witaj w Cierniodławach!$b$bMoże tego nie wiesz, ale tamten krasnolud to syn jedynego w swoim rodzaju Hemeta Nesingwary\'ego, słynnego bohatera wojennego Przymierza i mistrza polowań na grubą zwierzynę. Tak jak ojciec, niezbyt chętnie wita obcych w swoim obozie, ale ty wyglądasz na kogoś, kto swoje w życiu $gprzeżył:przeżyła;, $N.$b$bIdź i porozmawiaj z nim. To wykapany ojciec, więc może udzieli ci paru wskazówek łowieckich.', 'Porozmawiaj z Hemetem Nesingwarym juniorem.', '', 'Porozmawiaj z Hemetem Nesingwarym juniorem w Ekspedycji Nesingwary\'ego w Dolinie Cierniodławów.', '', '', '', '', 0),
(584, 'plPL', 'Głowy klanu Krwawych Skalpów', 'Głowy Yenniku nie było wśród tych głów, za co dziękuję Wielkiemu Wężowi. Ale wcale nie jesteśmy bliżej odnalezienia go.$B$BMusimy poznać prawdę, a obawiam się, że znają ją tylko wódz Krwawych Skalpów i jego znachor. To wrogowie plemienia Mrocznej Włóczni i nie powiedzą nic z własnej woli, więc musimy wydrzeć prawdę z ich martwych warg!$B$BPrzynieś mi głowy Gan\'zulaha i Nezzlioka Straszliwego i włóż je do tego kotła.$B$BSą w głębi Zul\'Kunda. Przynieś ich głowy... a potem zmusimy je do mówienia.', 'Przynieś głowę Gan\'zulaha i głowę Nezzlioka do bulgoczącego kotła w Obozie Grom\'gol.', '', 'Wróć do bulgoczącego kotła w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(585, 'plPL', 'Rozmowa z Nezzliokiem', '<Głowa Nezzlioka przemawia.>$B$BTo prawda. Wiem, dokąd zabrano dziecko Mrocznych Włóczni. $GPokonałeś:Pokonałaś; mnie i $gspętałeś:spętałaś; mojego ducha, ale nic nie powiem, dopóki nie zostanę udobruchany!$B$BKrwawe Skalpy toczą wojnę z Rozłupywaczami Czaszek. Aby zyskać moją przychylność, ukradnij Rozłupywaczom Czaszek 3 czaszki-trofea i złóż je tu, przy nas, aby mój duch miał niewolników w Otchłani. Jedna czaszka ma pochodzić ze stosu trofeów w Balia\'mah, druga z Ziata\'jai, a ostatnia z Zul\'Mamwe.', 'Przynieś trofeum z Balia\'mah, trofeum z Ziata\'jai i trofeum z Zul\'Mamwe do bulgoczącego kotła w Obozie Grom\'gol.', '', 'Wróć do bulgoczącego kotła w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(586, 'plPL', 'Rozmowa z Gan\'zulahem', '<Głowa Gan\'zulaha przemawia.>$B$BPrzeklinam cię! I przeklinam twoich przodków!!$B$BTylko krew i zemsta mogą ostudzić mój gniew, więc jeśli tego pragniesz... zrób tak:$B$BRzuć się w samo serce Rozłupywaczy Czaszek na wschodzie. Zabij najzacieklejszych z nich, a jeśli przeżyjesz... rozbij się o ich wodza, Ana\'theka Okrutnego. Ha! Przynieś mi jego roztrzaskaną zbroję, jeśli zdołasz!$B$BOby wyrwał ci kończyny i zostawił cię na pastwę zgnilizny i padlinożerców.', 'Zabij 8 łowców Rozłupywaczy Czaszek, 6 łowców głów Rozłupywaczy Czaszek i 4 berserkerów Rozłupywaczy Czaszek.$B$BPrzynieś zniszczoną zbroję Ana\'theka do bulgoczącego kotła w Obozie Grom\'gol.', '', 'Wróć do bulgoczącego kotła w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(587, 'plPL', 'Bez tabaki ani rusz', 'Ach, życie na morzu. Nie powiem, że to dobre życie, ale moje.$b$bKiedy zawijam do portu, lubię znaleźć sobie dobrą butelkę grogu i porządną tabakę. Paskudne nałogi, ale czym jest pirat bez swoich słabostek, co?$b$bWyobraź sobie, jak mi pękło serce, kiedy się okazało, że tutejszy zielarz wyprzedał cały zapas. Mówi, że jego dostawę przechwyciły te przeklęte Krwawe Żagle.$b$bZałożę się, że taki nieustraszony śmiałek jak ty zdołałby ich przekonać, żeby podzielili się towarem, co?', 'Deeg z Łupieżczej Zatoki chce, żebyś $gprzyniósł:przyniosła; mu 15 porcji tabaki.', '', 'Wróć do Deega w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(588, 'plPL', 'Los Yenniku', '<Nezzliok przemawia.>$B$B$GUdobruchałeś:Udobruchałaś; mnie i mojego wodza, więc powiem ci to, czego pragniesz się dowiedzieć...$B$BMłody Yenniku jest stracony dla swojego klanu.$B$BPorwał go znachor Zanzil Wygnaniec. Teraz Zanzil włada nim, ciałem i duszą, i tylko najpotężniejsza magia mogłaby go uwolnić.$B$BMagia, której ty nie posiadasz, $N.$B$BMoże twoi sojusznicy z Mrocznej Włóczni dadzą nadzieję na ocalenie Yenniku. Ale w to wątpię.', 'Porozmawiaj z Kin\'weelayem.', '', 'Porozmawiaj z Kin\'weelayem w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(589, 'plPL', 'Śpiewające kryształy', 'Legendy mówią o klejnocie ukrytym głęboko w sercu Cierniodławów. Nazywamy go Okiem umysłu i ma on wielką moc. Jeśli zdobędziesz to Oko, być może zdołamy za jego pomocą wyprowadzić zagubionego Yenniku z ciemności.$B$BPoradzę się duchów dżungli, gdzie szukać Oka umysłu. W tym czasie ty udaj się do Kopalni Kryształowej Żyły, na południowy wschód stąd, i zbierz pulsujące niebieskie odłamki z żelaznoszczękich bazyliszków. Odłamki są rzadkie, ale będziemy potrzebować ich magii, by nagiąć Oko umysłu do naszej woli.', 'Przynieś 3 pulsujące niebieskie odłamki Kin\'weelayowi w Obozie Grom\'gol.', '', 'Wróć do Kin\'weelaya w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(591, 'plPL', 'Oko umysłu', 'Oko umysłu ma ogrzy mag, na wschód stąd, głęboko w Ogrzym Kopcu Mosh\'Ogg. Nazywa się Mai\'Zoth. Znam go z czasów, gdy Mroczne Włócznie mieszkały w Cierniodławach – jest okrutny, a jego magia jest silna.$B$BA jeśli ma Oko umysłu, jego magia jest jeszcze silniejsza.$B$BMusisz stawić czoła Mai\'Zothowi i wydrzeć mu Oko umysłu. To niebezpieczne zadanie, ale to nasza jedyna nadzieja na ocalenie Yenniku.', 'Przynieś Oko umysłu Kin\'weelayowi w Obozie Grom\'gol.', '', 'Wróć do Kin\'weelaya w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(592, 'plPL', 'Ratunek dla Yenniku', 'Przekształciłem Oko umysłu w klejnot dusz. Służy dwóm celom: musisz go użyć, by ogłuszyć Yenniku, a gdy będzie ogłuszony, położyć mu go na głowie, by uwięzić jego duszę.$B$BPotem zanieś klejnot Nimboyi.$B$BYenniku przebywa z Zanzilem Wygnańcem w Ruinach Aboraz, na Kryształowym Brzegu, na dalekim Przylądku Cierniodławów.', 'Przynieś napełniony klejnot dusz Nimboyi.', '', 'Wróć do Nimboyi w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(593, 'plPL', 'Napełnianie klejnotu dusz', '', '', '', 'Wróć do Yenniku w Dolinie Cierniodławów.', '', '', '', '', 0),
(594, 'plPL', 'List w butelce', 'Liścik, napisany dość starannym pismem, brzmi:$B$BDo każdego, kto może mi pomóc –$B$BProszę, rozpaczliwie potrzebuję pomocy. Wielki niebiańskogrzywy trzyma mnie w niewoli na wyspie na Południowych Morzach.$B$BGwiazdy nocą są mi obce i przesłaniają je drzewa dżungli, ale w najpogodniejsze dni widzę na północnym zachodzie Dziki Brzeg, a na południowym zachodzie coś, co wygląda na duże żaglowce.$B$BBłagam cię, $gmój przyszły wybawco:moja przyszła wybawczyni;, pomóż mi.', 'Odnajdź autora listu w butelce.', '', 'Odnajdź autora listu w butelce gdzieś w Dolinie Cierniodławów.', '', '', '', '', 0),
(595, 'plPL', 'Krwawe Żagle', 'Widzę, że aż się rwiesz do roboty, kamracie. Nie wiem, czemu jakiś szczur lądowy taki jak ty chce pomagać Łupieżcom Czarnej Wody, ale nie zamierzam cię odprawiać.$b$bNasz statek właśnie przybił tu, w Łupieżczej Zatoce, a wieść niesie, że nasi rywale – te przeklęte, parszywe Krwawe Żagle – pojawiają się w całych południowych Cierniodławach.$b$bChłopaki są zbyt zajęci grogiem i szukaniem dziewek! Potrzebuję zwiadowcy.$b$bSprawdź zatoczkę na północ od Łupieżczej Zatoki, na Dzikim Wybrzeżu, i zobacz, co tam znajdziesz.', 'Pierwszy oficer Crazz chce, żebyś $gsprawdził:sprawdziła; zatoczkę na północ od Łupieżczej Zatoki.', '', '', '', '', '', '', 0),
(596, 'plPL', 'Zakrwawione kościane naszyjniki', 'Wysłano mnie do Grom\'gol, abym pomógł Nimboyi w jego misji, ale... ja też mam swoje powody, by tu być.$B$BPlemię Krwawych Skalpów jest wrogiem naszego plemienia. Zbieranie trofeów po wrogach daje nam nad nimi władzę. Możesz wesprzeć nasze plemię, polując na naszych wrogów.$B$BŻyją na północy. Zabijaj trolle Krwawych Skalpów i odbieraj im zakrwawione kościane naszyjniki. Zbierz ich wiele, a nagroda będzie wielka.', 'Przynieś 25 zakrwawionych kościanych naszyjników Kin\'weelayowi w Obozie Grom\'gol.', '', 'Wróć do Kin\'weelaya w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(597, 'plPL', 'Krwawe Żagle', 'Mapa przedstawia Łupieżczą Zatokę z czerwonym „X” narysowanym dokładnie w miejscu, w którym stoisz.$b$bNabazgrany tekst brzmi:$b$b„Macie rozbić obóz w tym miejscu i siedzieć cicho. Przed atakiem czekajcie na sygnał z południowego stanowiska dowodzenia. Jeśli ktoś się do was zbliży, zabijcie go.”', 'Zdaj pierwszemu oficerowi Crazzowi w Łupieżczej Zatoce raport z tego, co $godkryłeś:odkryłaś;.', '', 'Zdaj raport pierwszemu oficerowi Crazzowi w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(598, 'plPL', 'Pęknięty kościany naszyjnik', 'Skoro $gzebrałeś:zebrałaś; już trofea Krwawych Skalpów, mam dla ciebie kolejne zadanie. Plemię trolli Rozłupywaczy Czaszek żyje na południowym wschodzie, a od lat toczymy z nimi wojnę. Choć Mroczne Włócznie nie mieszkają już w Cierniodławach, wciąż wiąże nas konflikt z Rozłupywaczami Czaszek.$B$BPoluj więc na nich. Zbierz ich pęknięte kościane naszyjniki i wróć do mnie. Wesprzyj nas w naszej wojnie, a zaskarbisz sobie przyjaźń Mrocznych Włóczni.', 'Przynieś 25 pękniętych kościanych naszyjników Kin\'weelayowi w Obozie Grom\'gol.', '', 'Wróć do Kin\'weelaya w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(599, 'plPL', 'Krwawe Żagle', 'Niech mnie kule biją! Więc Krwawe Żagle szykują jakiś atak na Łupieżczą Zatokę? A to tupet tych łajdaków. W Łupieżczej Zatoce zawsze będą rządzić Łupieżcy Czarnej Wody!$b$bTo poważniejsza sprawa, niż myślałem. Natychmiast zdaj raport z tego, czego się $gdowiedziałeś:dowiedziałaś;, mistrzowi floty Morskiemu Rogowi! Ten stary morski wyga kręci się gdzieś po mieście...', 'Zamelduj mistrzowi floty Morskiemu Rogowi o planowanym ataku Krwawych Żagli.', '', 'Zdaj raport mistrzowi floty Morskiemu Rogowi w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(600, 'plPL', 'Wydobycie spółki Gitgeszeft', 'Spółka Gitgeszeft prowadzi w Cierniodławach całą sieć przedsięwzięć, przez które ciężko pracujące gobliny, takie jak ja, nie mogą uczciwie zarobić złota! Proszę, musisz mi pomóc!$B$BSpółka Gitgeszeft wydobywa kryształy w pobliżu Kopalni Kryształowej Żyły na północy. Do samej kopalni nie mogą wejść przez te wszystkie bazyliszki, ale wciąż wykopują śpiewające kryształy z okolicznych wzgórz.$B$BOdbierz im kryształy i pokaż, że dżungla nie należy do nich.$B$BI... eee... przynieś mi te kryształy jako dowód!', 'Przynieś 10 śpiewających niebieskich kryształów Crankowi Fizzlebubowi w Łupieżczej Zatoce.', '', 'Wróć do Cranka Fizzlebuba w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(601, 'plPL', 'Żywiołaki wody', 'Żywiołaki wody bez wątpienia przywołał Gazban, goblin czarodziej, który podobno odkrył Kamień Pływów. Jak być może wiesz, Kamień Pływów przeklina swojego posiadacza – ten raz po raz znika i pojawia się z powrotem...$b$bMoże uda nam się znaleźć sposób, by przeciwdziałać tej klątwie. Mag z Dalaranu mógłby zbadać magiczne pozostałości na karwaszach któregoś z żywiołaków wody. Musisz wrócić na wyspę i zdobyć kilka okazów.', 'Zdobądź 6 karwaszy żywiołaka wody dla barona Revilgaza z Łupieżczej Zatoki.', '', 'Wróć do barona Revilgaza w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(604, 'plPL', 'Krwawe Żagle', 'Crazz wysoko ceni twoje oddanie Łupieżcom Czarnej Wody. Powierzę ci misję niezwykłej wagi dla floty.$b$bPrzeniknij do tak zwanego południowego stanowiska dowodzenia, które Krwawe Żagle założyły na Dzikim Brzegu. Napadnij na obozowisko. Przynieś mi ich mapy morskie i pisemne rozkazy. Zobaczymy, co dokładnie knują te szumowiny.', 'Mistrz floty Morski Róg z Łupieżczej Zatoki chce, żebyś $gzabił:zabiła; 10 awanturników Krwawych Żagli i $gprzyniósł:przyniosła; mapy morskie Krwawych Żagli oraz rozkazy Krwawych Żagli.', '', 'Wróć do mistrza floty Morskiego Rogu w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(605, 'plPL', 'Śpiewające niebieskie odłamki', 'Śpiewające kryształy występują tylko w Cierniodławach i są bardzo cenne dla pewnych osób. Potrafię upłynnić te kryształy, ale przeklęta spółka Gitgeszeft utrudnia uczciwemu przedsiębiorcy takiemu jak ja zdobycie choćby jednego!$B$BChciałbym cię zatrudnić.$B$BBazyliszki w Cierniodławach jedzą kryształ. Dzięki temu mają twardą skórę, z której czasem da się pozyskać kryształ przyzwoitej jakości.$B$BMożesz go zdobyć z każdego bazyliszka, ale te mniej groźne żyją na brzegach na południe od Zul\'Kunda, na północy.', 'Przynieś 10 odłamków śpiewającego kryształu Crankowi Fizzlebubowi.', '', 'Wróć do Cranka Fizzlebuba w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(606, 'plPL', 'Postrach dla Roztrzęsionego', 'Jeśli czegoś nie znoszę, to ludzi, którzy nie spłacają długów karcianych! A sporo osób jest mi winnych. Myślisz, że pomożesz mi je ściągnąć?$B$BNajpierw „Roztrzęsiony” Phillipe, tam przy dokach. Po grze w zeszłym tygodniu jest mi winien kupę forsy i chcę swojej należności! Ale żeby ją dostać, musimy go nastraszyć.$B$BWyjdź z miasta i poluj na starsze goryle z Mglistej Doliny. Nazbieraj ładnych podrobów, a potem zanieś je Roztrzęsionemu. Nie zdradzaj, że są ze zwierzęcia – niech myśli najgorsze.', 'Przynieś 5 podrobów z Mglistej Doliny „Roztrzęsionemu” Phillipe\'owi w Łupieżczej Zatoce.', '', 'Wróć do „Roztrzęsionego” Phillipe\'a w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(607, 'plPL', 'Powrót do MacKinleya', 'Masz, weź tę sakiewkę i daj ją Wilkowi Morskiemu. I powiedz mu, że chciałem mu oddać! Przysięgam!!$B$BPo prostu trochę się upiłem i zabłądziłem, i... wiesz, jak to jest. Zrozumie – nie musisz być $gbrutalny:brutalna;!', 'Zanieś zapłatę Roztrzęsionego „Wilkowi Morskiemu” MacKinleyowi.', '', 'Zdaj raport „Wilkowi Morskiemu” MacKinleyowi w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(608, 'plPL', 'Krwawe Żagle', 'Niech szlag trafi bezczelność Firallona! Nie przepłynąłby łódką po Kryształowym Jeziorze, a co dopiero poprowadzić na nas całą flotę.$b$bKrwawe Żagle zapłacą za swoją lekkomyślność. Skoro znamy już ich plan ataku, możemy uderzyć, zanim się zorientują, co ich trafiło.$b$bAle po co wysyłać całą flotę do roboty, z którą poradzi sobie jedna dzielna drużyna śmiałków? $n, zabierz kilku najzdolniejszych towarzyszy do miejsca lądowania Firallona i zgładź dowództwo Krwawych Żagli. Ich flota pójdzie na dno niedługo potem...', 'Mistrz floty Morski Róg z Łupieżczej Zatoki chce, żebyś $gzabił:zabiła; kapitana Cichą Wodę, kapitana Przeciągacza i dowódcę floty Firallona.', '', 'Wróć do mistrza floty Morskiego Rogu w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(609, 'plPL', 'Długi wudu', 'Moja lista się skraca, ale wciąż są ludzie, którzy mi zalegają.$B$BNastępni są Maury „Szpotawa Stopa” Wilkins, Jon-Jon Wrona i Chucky „Dziesięć Kciuków”.$B$BTe parszywe psy od miesięcy nie spłacają długów i myślałem, że zwiali z miasta, żeby się wymigać! Później usłyszałem, że zostali przeklęci i zaczarowani, i teraz błąkają się po ruinach w dżungli. Ale nie obchodzi mnie, jaki spotkał ich los – chcę tego, co moje!$B$BSą w Ruinach Aboraz i Ruinach Jubuwal, na północny wschód stąd. Znajdź ich i ściągnij dług.', 'Przynieś szpotawą stopę Maury\'ego, złotą lunetę Jon-Jona i ogromny pierścień Chucky\'ego „Wilkowi Morskiemu” MacKinleyowi w Łupieżczej Zatoce.', '', 'Wróć do „Wilka Morskiego” MacKinleya w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(610, 'plPL', '„Ślicznotek” Duncan', 'Mój OJCIEC cię przysłał? Myślałam, że ten stary zrzęda już dawno machnął na mnie ręką.$b$bTo nie była tak naprawdę jego wina, że uciekłam. Po prostu nie powinien oczekiwać, że zechcę wieść nudne życie, ślęcząc nad zatęchłymi księgami i obracając się wśród siwowłosych, sztywnych, nadętych magów!$b$bJeśli potrzebujesz mojego sztyletu, musisz go odebrać „Ślicznotkowi” Duncanowi, jednemu z Krwawych Żagli. Wbij mu coś między łopatki, a na pewno go odda.', 'Odbierz sztylet Catelyn „Ślicznotkowi” Duncanowi.', '', 'Wróć do Catelyn Ostrze w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(611, 'plPL', 'Klątwa Pływów', 'Więc szukasz jakiegoś ołtarza? No cóż, nie jestem znawczynią trollowych ruin jak mój ojciec, ale słyszałam o zatopionym trollowym mieście niedaleko wyspy, której szukasz. Może spróbuj tam.$b$b$GOdzyskałeś:Odzyskałaś; dla mnie nóż, więc chyba mogę ci go pożyczyć... ale chcę go z powrotem, kiedy skończysz!', 'Zniszcz Ołtarz Pływów ostrzem Catelyn, zabij Gazbana i przynieś Kamień Pływów oraz ostrze Catelyn baronowi Revilgazowi.', '', 'Wróć do barona Revilgaza w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(612, 'plPL', '', 'To mało prawdopodobne, ale może zdołasz przekonać Catelyn, żeby rozstała się ze swoim sztyletem? Serce kolekcjonera, wiesz, jak to jest.$b$bMoże jeśli wspomnisz, że to dla mnie, chętniej mi go sprzeda.', 'Zwróć ostrze Catelyn.', '', 'Wróć do Catelyn Ostrze w Dolinie Cierniodławów.', '', '', '', '', 0),
(613, 'plPL', 'Rozłupać stopę Maury\'ego', 'Do diaska! Ten majtek Maury założył kłódkę na swoją stopę i nie mogę jej otworzyć! Jego łup jest w stopie, a to właśnie jest mi winien!$B$BMusimy znaleźć klucz do tej kłódki. Maury słynął z tego, że grywał z ogrami Mosh\'Ogg w ich kopcu na północnym wschodzie. A kiedy jeszcze żył, powiedział mi, że ostatnim razem, gdy był w kopcu, przegonili go, bo za dużo wygrał. Może tamtejsze ogry mają jego klucz.$B$BAle jeśli tak, być może będziesz $gmusiał:musiała; wybić całą masę, żeby trafić na tego właściwego...', 'Przynieś klucz Maury\'ego „Wilkowi Morskiemu” MacKinleyowi w Łupieżczej Zatoce.', '', 'Wróć do „Wilka Morskiego” MacKinleya w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(614, 'plPL', 'Skrzynia kapitana', 'Kiedyś pływałem statkiem stąd aż do Zapadki w Kalimdorze. Byłem kapitanem, któremu się wiodło, o nieskazitelnej reputacji.$B$BAż...$B$BTe przeklęte morskie olbrzymy mnie zrujnowały! Rozbiły mój statek, zabiły załogę, a mnie puściły szalupą do Łupieżczej Zatoki. A jeden z olbrzymów, Gorlash, ukradł moją kapitańską skrzynię. Powiedział, że przyda mu się na tabakierkę. Co za tupet!$B$BSłyszałem, że Gorlash wędruje po wybrzeżu na wschód stąd. Znajdź go i odzyskaj moją skrzynię! Zrób to, a zaskarbisz sobie wdzięczność kapitana.', 'Przynieś skrzynię Smottsa Hecklebury\'emu Smottsowi w Łupieżczej Zatoce.', '', 'Wróć do kapitana Hecklebury\'ego Smottsa w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(615, 'plPL', 'Kordelas kapitana', 'Kiedy straciłem przez te olbrzymy pierwszy statek, kupiłem drugi. Nazwałem go „Zemsta Smottsa”, załadowałem zapasami, zebrałem załogę i wyruszyłem na poszukiwanie tych łotrów. Znalazłem ich, ale... pokonali mnie. Rozbili „Zemstę Smottsa”, zabili moją drugą załogę i znów puścili mnie szalupą.$B$BTym razem inny olbrzym, Negolash, ukradł mój kordelas.$B$BZmierz się z Negolashem i przynieś mi mój kordelas!$B$BPorozmawiaj ze Sproggerem. Był kucharzem na „Zemście Smottsa” i przeżył ostatni atak. Pomoże ci znaleźć olbrzyma.', 'Porozmawiaj ze Sproggerem.', '', 'Porozmawiaj ze Sproggerem w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(616, 'plPL', 'Nawiedzona wyspa', 'Baron Revilgaz kazał mi nadstawiać ucha na pogłoski o dziwnych i niezwykłych rzeczach w Łupieżczej Zatoce i w Cierniodławach. Zwykle nie przywiązuję wagi do opowieści o duchach, ale w karczmie słyszałem, jak paru żeglarzy gadało o nawiedzonej wyspie niedaleko wybrzeża. Mówią, że są tam żywiołaki wody i duch goblina, który bredzi jak szalony.$b$bJeśli idziesz porozmawiać z Revilgazem, $gmógłbyś:mogłabyś; mu przekazać tę historię?', 'Porozmawiaj z baronem Revilgazem w Łupieżczej Zatoce.', '', 'Porozmawiaj z baronem Revilgazem w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(617, 'plPL', 'Akiris na wiązki', 'Szukasz roboty, $N? Może coś się znajdzie, jeśli nie boisz się małego wyzwania.$B$BMam kumpla imieniem Groy, który zbija fortunę na sprzedaży czegoś, co nagi nazywają trzciną akiris: to jakaś cenna morska trzcina. Nie bardzo wiem, do czego służy, ale dobrze płaci za wiązki tego towaru.$B$BPrzynieś mi dziesięć łodyg, a zrobimy interes. Nagi widziano ostatnio na plaży na północ stąd.', 'Przynieś 10 wiązek trzcin akiris kaprowi Bloadsowi w Łupieżczej Zatoce.', '', 'Wróć do kapra Bloadsa w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(618, 'plPL', 'Starcie z Negolashem', 'Negolash to wiecznie głodny olbrzym.$B$BKiedy olbrzymy zniszczyły nasz statek, Negolash ruszył prosto do mojej kuchni. Nie łaknął załogi jak inne olbrzymy. Negolash chciał wina... i moich skrzydeł sępa z grilla. To moja specjalność – po przepis musiałem jechać aż na Bezludzie!$B$BJeśli chcesz zwabić olbrzyma, zdobądź trochę wina i stos skrzydeł sępa. Połóż je w naszej starej szalupie, na południowy wschód stąd, na wybrzeżu. Kiedy Negolash poczuje całe to jedzenie, na pewno przyjdzie!', 'Zanieś 10 skrzydeł sępa z grilla i 5 butelek wina z dżunglowej winorośli do szalupy kapitana Smottsa.$B$BZabij Negolasha i przynieś kordelas Smottsa kapitanowi Smottsowi w Cierniodławach.', '', 'Wróć do kapitana Hecklebury\'ego Smottsa w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(619, 'plPL', 'Przynęta na Negolasha', '', '', '', 'Wróć do zniszczonej szalupy w Dolinie Cierniodławów.', '', '', '', '', 0),
(620, 'plPL', 'Szarfa z monogramem', 'Na brzegu tej pięknej szarfy wyhaftowano litery „HS”.', 'Zwróć szarfę z monogramem jej właścicielowi.', '', 'Znajdź właściciela szarfy z monogramem w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(621, 'plPL', 'Sekret Zanzila', 'Zanzil Wygnaniec mieszka ze swoimi wyznawcami w Ruinach Jubuwal i Aboraz, na północny wschód od Łupieżczej Zatoki. Został wygnany ze swojego plemienia. Dlaczego? Cóż...$B$BZanzil zna sposoby naginania cudzych umysłów i jego przywódcy się go boją. Na swoich wyznawcach stosuje miksturę z roślin dżungli, która tłumi ich wolę i wzmacnia ich ciała.$B$BJego mikstura byłaby wiele warta dla tych, którzy chcą kontrolować innych.$B$BPrzynieś mi próbki jego mikstury, a znajdę dla nich zastosowanie.', 'Przynieś 12 próbek mikstury Zanzila Crankowi Fizzlebubowi w Łupieżczej Zatoce.', '', 'Wróć do Cranka Fizzlebuba na Dzikim Brzegu w Dolinie Cierniodławów.', '', '', '', '', 0),
(622, 'plPL', 'Powrót do kaprala Kaleba', 'Kiedy cię nie było, naprawiłem garnek, który $gprzyniosłeś:przyniosłaś;. Dodałem nawet dodatkowy gwizdek parowy, i patrz! Na dnie jest nowy siekacz, który przetnie nawet kości udowe!$B$BTak, tak, wolnowar Krazeka to stuprocentowa radość kucharza! Jestem pewien, że jego właściciel będzie zadowolony.', 'Zanieś naprawiony garnek Krazeka kapralowi Kalebowi w Obozie Buntowników.', '', 'Zdaj raport kapralowi Kalebowi w Obozie Buntowników w Dolinie Cierniodławów.', '', '', '', '', 0),
(623, 'plPL', 'Akiris na wiązki', '$N, skoro już tu jesteś: kiedy cię nie było, dostałem wiadomość od Groya. Pisze, że jest zadowolony z ostatniej dostawy, a ma klienta, który chce więcej tego towaru, i to od razu.$B$BJa przez tydzień nie wybieram się do Theramore, ale jeśli masz ochotę na podróż, nic nie stoi na przeszkodzie, żebyś $gzawiózł:zawiozła; mu towar za mnie.$B$B$GŻądny:Żądna; przygód? Wiesz chyba, gdzie jest Pyłowe Bagnisko, co? Ale uważaj, w Theramore może być niebezpiecznie, jeśli trafisz na niewłaściwe towarzystwo.', 'Przynieś wiązkę trzcin akiris kaprowi Groyowi w Theramore.', '', '', '', '', '', '', 0),
(624, 'plPL', 'Zagadka Cortella', 'Jest most zdobiony, co wielu wędrowców zna,$bNa wschód od Wichrowej Zguby, na południe od Rudej Grani trwa.$bPod nim czeka coś dla ciebie, uwierz mi,$bJedni zwą to wskazówką, drudzy – tropem, co w mroku lśni.$bTam leżeć będzie po kres wszystkich dni,$bCzekając na Moczarach Smutków, aż ktoś ją znajdzie – może ty.', 'Rozwiąż zagadkę!', '', 'Znajdź wskazówkę na Moczarach Smutków.', '', '', '', '', 0),
(625, 'plPL', 'Zagadka Cortella', 'Daleki ląd w Kalimdorze czeka na ciebie,$bGdzie groza nadzieje i losy pogrzebie.$bNa wschód od Pustkowi pogoda jest sroga,$bNa Pyłowym Bagnisku mrok, niebezpieczeństwo i trwoga.$bLecz czeka tam wskazówka dla tych, co nie znają lęku,$bW jaskini na południowym zachodzie – masz ją niemal w ręku.', 'Rozwiąż zagadkę!', '', 'Znajdź wskazówkę na Pyłowym Bagnisku.', '', '', '', '', 0),
(626, 'plPL', 'Zagadka Cortella', 'Do Lordaeronu! Do krainy zamętu i trwogi,$bGdzie dzielni żołnierze ze śmiercią ścierają się wśród pożogi.$bZnajdź drogę przez wielkie wzburzenie,$bTam tej wyprawy czeka zakończenie.$bWzdłuż wybrzeża Zaziemia, u podnóża wielkich wodospadów,$bPod wodą twój skarb woła – ruszaj jego śladem!', 'Rozwiąż zagadkę!', '', 'Znajdź wskazówkę w Zaziemiu.', '', '', '', '', 0),
(627, 'plPL', 'Przysługa dla Krazeka', 'W Wąwozie Suchowąsów, daleko na północy, na Wyżynach Aratorskich, jest górska jaskinia. W tej jaskini znajduje się rzadka ruda: krwawnik. Krwawnik z tej jaskini nie jest najwyższej próby, ale nawet krwawnik niskiej jakości jest cenny... dla tych, którzy wiedzą, jak go użyć.$B$BChciałbym trochę go mieć.$B$BNaprawię twój wolnowar, ale kiedy będę nad nim pracował... przynieś mi próbki krwawnika. Przynieś wystarczająco dużo, a dorzucę ci nawet premię.$B$BAch, i jeśli nie umiesz go wydobywać... znajdź kogoś, kto umie!', 'Przynieś 4 ładunki rudy pomniejszego krwawnika Krazekowi w Łupieżczej Zatoce.', '', 'Wróć do Krazeka w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(628, 'plPL', 'Wzniosłe buty', 'Wnętrze gotowe, zostało tylko dodać warstwę zewnętrzną. Do tego używam wyłącznie najlepszych skór starszych krokoliszków. Są trwalsze i stanowią lepsze płótno, że tak powiem, dla wzorów i ozdób, które wyróżniają Wzniosłe buty Drizzlika.$b$bTrudno jednak znaleźć tę idealną skórę – do mojego planu pasuje tylko skóra starszego słonowodnego krokoliszka. Starsze osobniki wychodzą tylko wtedy, gdy bronią innych słonowodnych krokoliszków, więc może trzeba będzie zabić kilka, żeby któregoś wywabić.', 'Przynieś skórę starszego krokoliszka Drizzlikowi w Łupieżczej Zatoce.', '', 'Wróć do Drizzlika w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(629, 'plPL', 'Plugawa Rafa', 'Dawno temu wielki wstrząs ziemi pogrążył stare trollowe miasto w wodach Dzikiego Wybrzeża na północnym zachodzie. Nazywamy to miejsce Plugawą Rafą, bo w ruinach miasta mieszkają teraz murloki, które atakują każdego, kto się zbliży.$B$BWśród tych ruin jest stara tablica, która opowiada starożytną historię Gri\'leka, bohatera trollowych legend. Ta opowieść jest święta dla plemienia Mrocznej Włóczni i choć tablica jest zbyt duża, by ją przenieść, chcę mieć jej odłamek, by umieścić go w świątyni naszego nowego domu w Orgrimmarze.', 'Przynieś odłamek tablicy Kin\'weelayowi w Obozie Grom\'gol.', '', 'Wróć do Kin\'weelaya w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(630, 'plPL', 'List w butelce', '$N, pokładam wiarę w tobie i w każdym, kogo zdołasz zebrać, by mnie uwolnić. Moim ciemięzcą jest wielki niebiańskogrzywy Król Mukla. Rządzi zwierzętami tej wyspy, a one trzymają mnie tu wbrew mojej woli za pomocą tego łańcucha. Jeśli zdołasz go zabić i znaleźć klucz do tych kajdan, będę ci ogromnie wdzięczna.$B$BCzęsto słyszę go w południowo-wschodniej części wyspy, ale proszę, uważaj: z nim nie ma żartów.', 'Zabij Króla Muklę i wróć z kluczem do Księżniczki Poobah, aby ją uwolnić.', '', 'Wróć do Księżniczki Poobah na Wyspie Jaguero w Dolinie Cierniodławów.', '', '', '', '', 0),
(648, 'plPL', 'Ratuj OOX-17/TN!', 'Z robota znów dobiega trzeszczący głos gnoma:$B$B„Muszę przemieścić OOX-17/TN w otwarte, bezpieczne miejsce, żeby mógł rozpocząć długą procedurę startową. Ma wbudowany kamuflaż, ale potrzebuję czasu po mojej stronie, żeby go znowu uruchomić. Odeskortuj robota z jego obecnego położenia, powiedzmy, w pobliże Jaskiń Czasu! To powinno być idealne miejsce i wystarczająco długa droga, żebym zdążył wszystko uruchomić!”$B$B„Odeskortuj go bezpiecznie, a potem przyjdź do mnie do Łupieżczej Zatoki! Oglethorpe Obnoticus – bez odbioru!”', 'Odeskortuj OOX-17/TN w bezpieczne miejsce, a następnie zamelduj się u Oglethorpe\'a Obnoticusa w Łupieżczej Zatoce.', 'Odeskortuj OOX-17/TN w bezpieczne miejsce', 'Wróć do Oglethorpe\'a Obnoticusa w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(836, 'plPL', 'Ratuj OOX-09/HL!', 'Z robota znów dobiega trzeszczący głos gnoma:$B$B„Muszę przemieścić OOX-09/HL w otwarte, bezpieczne miejsce, żeby mógł rozpocząć długą procedurę startową. Ma wbudowany kamuflaż, ale potrzebuję czasu po mojej stronie, żeby go znowu uruchomić. Odeskortuj robota z jego obecnego położenia, powiedzmy, do jakichś dużych skał, które zasłaniają widok! To powinno być idealne miejsce i wystarczająco długa droga, żebym zdążył wszystko uruchomić!”$B$B„Odeskortuj go bezpiecznie, a potem przyjdź do mnie do Łupieżczej Zatoki! Oglethorpe Obnoticus – bez odbioru!”', 'Odeskortuj OOX-09/HL w bezpieczne miejsce, a następnie zamelduj się u Oglethorpe\'a Obnoticusa w Łupieżczej Zatoce.', 'Odeskortuj OOX-09/HL w bezpieczne miejsce', 'Wróć do Oglethorpe\'a Obnoticusa w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(1036, 'plPL', 'Ahoj, obwiesiu', '$N... tak, słyszałem o tobie. Słyszałem, że nie jesteś $gprzyjacielem:przyjaciółką; Łupieżczej Zatoki – tak jak my, Krwawe Żagle. Dowódca floty Firallon szuka na specjalną misję $gkrzepkich i dziarskich chłopów:krzepkich i dziarskich dziewek; takich jak ty.$B$BJeśli jesteś $gzainteresowany:zainteresowana;, wybierz się na „Szkarłatny Welon” i porozmawiaj z nim pod pokładem. Stoi na kotwicy u Dzikiego Brzegu, na wschód stąd, obok „Rwącego Prądu” i „Szczęścia Panny”.', 'Porozmawiaj z dowódcą floty Firallonem na pokładzie „Szkarłatnego Welonu” u wybrzeży Doliny Cierniodławów.', '', '', '', '', '', '', 0),
(1116, 'plPL', 'Pył snów z moczarów', 'Zdobycie informacji o Nazzie to spora przysługa, $N. O tak, spora. Ale $gprzybyłeś:przybyłaś; aż z Migoczących Równin, żeby je dostać... chcesz jeszcze trochę popodróżować?$B$BPodczas gdy ja skontaktuję się ze swoimi źródłami, może zdobędziesz coś dla mnie, co?$B$BHm... co by to mogło być? Może pył snów od smoczych piskląt z Moczarów Smutków. Tak, chętnie dosypałbym trochę pyłu snów do mojej sakiewki z tabaką!$B$BZdobądź go dla mnie, $N, a dam ci informacje, których szukasz.', 'Przynieś 10 szczypt pyłu snów Krazekowi w Łupieżczej Zatoce. Pył snów można zdobyć od smoczych piskląt z Moczarów Smutków.', '', 'Wróć do Krazeka na Dzikim Brzegu w Dolinie Cierniodławów.', '', '', '', '', 0),
(1127, 'plPL', 'Stout głupca', 'Więc chcesz trochę Stoutu głupca, co? Myślisz o powrocie na wyścigi...?$B$BNiech będzie, przynieś mi więcej mikstury Zanzila, a zrobię ci więcej stoutu.', 'Przynieś 12 porcji mikstury Zanzila Crankowi Fizzlebubowi w Łupieżczej Zatoce.', '', 'Wróć do Cranka Fizzlebuba w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(1240, 'plPL', 'Trollowy znachor', 'Musimy poznać okoliczności śmierci Marga! A jedyny sposób, $N, to czarownicza magia trolli.$B$BZanieś głowę Marga Kin\'weelayowi do Obozu Grom\'gol w Dolinie Cierniodławów.$B$BKin\'weelay to najpotężniejszy znachor trolli Mrocznej Włóczni. Jeśli ktokolwiek potrafi przemówić do ducha Marga Nocnego Oka, to właśnie on.', 'Zanieś głowę hardego orka Kin\'weelayowi w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', '', '', 0),
(1261, 'plPL', 'Marg przemawia', 'Przeklęty mułoskorupy! Nie da się zabić Marga! Ach, ale ja nie żyję. Więc jednak mnie zabił...$B$BAle moja misja! Moja misja! Ty, $N, musisz ją dokończyć.$B$BNieopodal Theramore wypatrzyłem grupę żołnierzy Przymierza obozujących na plaży. A jeden z żołnierzy nosił wisior... wisior wysadzany tyloma klejnotami, że żadnego żołnierza nie byłoby na niego stać!$B$BTamtej nocy zakradłem się do ich obozu i ukradłem wisior, ale w drodze powrotnej do bazy zabił mnie mułoskorupy krabolud!$B$B$N, musisz odnaleźć tego mułoskorupego i odzyskać wisior!', 'Przynieś wysadzany klejnotami wisior Nazeerowi w Paprotni.', '', 'Wróć do Nazeera Krwawej Piki w Paprotni na Pyłowym Bagnisku.', '', '', '', '', 0),
(2760, 'plPL', 'Zakon Mithrilu', 'Większość naszych rekrutów nigdy nie dociera do Łupieżczej Zatoki, $N. Blask insygnium wystarczy, by obudzić żądzę łupu nawet w najbardziej nieugiętym kowalu. Głupcy z nich, bo insygnium to kropla w morzu w porównaniu z bogactwem przedmiotów, które zobaczysz!$B$BOdszukaj Galvana Prastarego i pokaż mu tę odznakę. Mieszka daleko na północy, między Zul\'Gurub a Ogrzym Kopcem Mosh\'Ogg.$B', 'Porozmawiaj z Galvanem Prastarym w Dolinie Cierniodławów.$B', '', '', '', '', '', '', 0),
(2761, 'plPL', 'Wytapiaj, przetapiaj', 'Wielu kowali uważa, że górnictwo i kowalstwo to osobne, niezależne zajęcia. Ale czy może istnieć kowalstwo bez górnictwa? Aha – to niemożliwe! Wprawny kowal musi być też wprawnym górnikiem.$B$BPokaż Galvanowi, że się nadajesz, $N. Przynieś mi czterdzieści sztabek żelaza i czterdzieści sztabek mithrilu. W zamian Galvan nauczy cię sekretów zdobionych mithrilowych spodni!', 'Przynieś czterdzieści sztabek mithrilu i czterdzieści sztabek żelaza Galvanowi Prastaremu w Cierniodławach.', '', 'Wróć do Galvana Prastarego w Dolinie Cierniodławów.', '', '', '', '', 0),
(2762, 'plPL', 'Wielki srebrny oszust', 'Mówi się, że srebryt jest mocniejszy i trwalszy od mithrilu. Galvan nie spiera się z taką oceną tych minerałów, ale wbrew swojej nazwie srebryt wcale nie jest prawdziwym srebrem! Mithril to znacznie szlachetniejszy minerał! HA! Tak czy inaczej, do tej lekcji musisz znaleźć wielkiego srebrnego oszusta, $N.$B$BPrzynieś mi czterdzieści sztabek mithrilu i pięć sztabek srebrytu. W zamian poznasz sekret zdobionych mithrilowych rękawic, a co ważniejsze – przekonasz się, że srebryt to kłamca!', 'Przynieś czterdzieści sztabek mithrilu i pięć sztabek srebrytu Galvanowi Prastaremu w Cierniodławach.', '', 'Wróć do Galvana Prastarego w Dolinie Cierniodławów.', '', '', '', '', 0),
(2763, 'plPL', 'Sztuka nasycania', 'Pozyskiwanie cennych kamieni ma dla naszego rzemiosła ogromne znaczenie, $N. Niewiele klejnotów jest cenniejszych od cytrynu. Magiczne właściwości, którymi nasycamy nasze wyroby, stają się znacznie silniejsze w obecności cytrynu.$B$BNa tej lekcji wzmocnimy czterdzieści sztabek mithrilu czterema cytrynami. W efekcie lepiej zrozumiesz magiczną gemmologię i zdobędziesz wiedzę, jak wykuwać zdobione mithrilowe naramienniki.', 'Przynieś czterdzieści sztabek mithrilu i cztery cytryny Galvanowi Prastaremu w Cierniodławach.', '', 'Wróć do Galvana Prastarego w Dolinie Cierniodławów.', '', '', '', '', 0),
(2764, 'plPL', 'Najlepszy uczeń Galvana', 'Jeśli chcesz zakończyć szkolenie u Galvana, wybierz się do Gadżetonu.$B$BZnajdziesz tam mojego najlepszego ucznia: Trentona Światłomłota. Może cię wiele nauczyć o zdobionym mithrilu. W przeciwnym razie zostań tutaj i się ucz!$B$BAch, Gadżeton leży w Tanaris, rzecz jasna!', 'Porozmawiaj z Trentonem Światłomłotem w Gadżetonie w Tanaris.', '', '', '', '', '', '', 0),
(2765, 'plPL', 'Kowalstwo (ekspert)!', 'Gdy $gprzyszedłeś:przyszłaś; do mnie po raz pierwszy, wiedziałem, że wyrośnie z ciebie jeden z moich najlepszych uczniów! Bez wahania $goddałeś:oddałaś; McGavanowi talizman o niemałej mocy. $GZrobiłeś:Zrobiłaś; to tylko po to, by mnie poznać. Taka ślepa wiara i oddanie rzemiosłu zasługują na nagrodę.$B$B$GOsiągnąłeś:Osiągnęłaś; biegłość w kowalstwie, $N. Zbierz owoce swojej pracy!', 'Odbierz nagrodę od Galvana Prastarego!', 'Główna wygrana jest twoja', 'Wróć do Galvana Prastarego w Dolinie Cierniodławów.', '', '', '', '', 0),
(2767, 'plPL', 'Ratuj OOX-22/FE!', 'Z robota znów dobiega trzeszczący głos gnoma:$B$B„Muszę przemieścić OOX-22/FE w otwarte, bezpieczne miejsce, żeby mógł rozpocząć długą procedurę startową. Ma wbudowany kamuflaż, ale potrzebuję czasu po mojej stronie, żeby go znowu uruchomić. Odeskortuj robota z jego obecnego położenia, powiedzmy, do głównej drogi! To powinno być idealne miejsce i wystarczająco długa droga, żebym zdążył wszystko uruchomić!”$B$B„Odeskortuj go bezpiecznie, a potem przyjdź do mnie do Łupieżczej Zatoki! Oglethorpe Obnoticus – bez odbioru!”', 'Odeskortuj OOX-22/FE w bezpieczne miejsce, a następnie zamelduj się u Oglethorpe\'a Obnoticusa w Łupieżczej Zatoce.', 'Odeskortuj OOX-22/FE w bezpieczne miejsce', 'Wróć do Oglethorpe\'a Obnoticusa w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(2864, 'plPL', 'Tran\'rek', 'Mój kuzyn Tran\'rek ma kłopoty. Tygodnie temu obiecał mi ładunek pancerzy skarabeuszy i dotąd go nie dostarczył. To mój kuzyn, więc wolałbym nie wysyłać nikogo do Gadżetonu, żeby mu coś połamał.$B$BMożesz porozmawiać za mnie z Tran\'rekiem? Daj mu do zrozumienia, że ma skompletować tę dostawę, zanim zrobię coś pochopnego.$B$BGadżeton leży w północnym Tanaris, w Kalimdorze.', 'Porozmawiaj z Tran\'rekiem w Gadżetonie.', '', '', '', '', '', '', 0),
(2872, 'plPL', 'Dług Stoleya', 'Mój stary kumpel Stoley wisi mi bardzo szczególną butelkę rumu. Prowadzi bar w Porcie Parochlebców w Tanaris, w Kalimdorze, i zaklinał się, że tamtejszy rum jest mocniejszy od wszystkiego, co znajdziemy w Łupieżczej Zatoce. Jest tak pewny swego, że mówi: jeśli spróbuję tego rumu i się z nim nie zgodzę, podwoi dług, który ma u mnie!$B$BTyle że chyba nie jest już tak pewny siebie jak wtedy, gdy ostatnio rozmawialiśmy, i teraz boi się dać mi ten rum. Ale ja się z zakładów nie wycofuję, więc może pogadasz z nim w moim imieniu...', 'Porozmawiaj ze Stoleyem w Porcie Parochlebców.', '', '', '', '', '', '', 0),
(2874, 'plPL', 'Dostawa dla MacKinleya', 'Jeszcze raz dzięki za pomoc, $N. Oto butelka zęzowego rumu Parochlebców. Zanieś ją MacKinleyowi, a wreszcie pożegna się ze swoimi szalonymi przekonaniami o gorzale z Łupieżczej Zatoki.', 'Zanieś butelkę Stoleya „Wilkowi Morskiemu” MacKinleyowi w Łupieżczej Zatoce.', '', '', '', '', '', '', 0),
(2932, 'plPL', 'Ponure przesłanie', 'Trolle Suchokorych były niegdyś sojusznikami Hordy, ale zdradziły Thralla... i muszą za to ponieść karę!$B$BMasz, weź moją pikę i idź do Zaziemia, daleko na północ. Znajdziesz je na północny wschód od Smolnego Młyna, wioski w rękach naszych sojuszników, Porzuconych.$B$BGdy dotrzesz do Zaziemia, poluj na trolle Suchokorych. Zbierz ich czaszki i wbij moją pikę w ziemię w jednej z ich mniejszych wiosek, Hiri\'watha lub Zun\'watha.$B$BPokaż im, że ich podłe czyny mają swoje konsekwencje!', 'Zbierz czaszki Suchokorych i nabij je na pikę Nimboyi. Umieść obładowaną pikę Nimboyi w jednej z wiosek Suchokorych w Zaziemiu, a następnie wróć do Nimboyi w Cierniodławach.', 'Pozostaw ponure przesłanie.', 'Wróć do Nimboyi w Obozie Grom\'gol w Dolinie Cierniodławów.', '', '', '', '', 0),
(3621, 'plPL', 'Wykuwanie zguby spaczenia', 'Broń jest gotowa do wykucia. Musisz zanieść hartowany azsharyt komuś, kto potrafi okiełznać energię spaczenia.$B$BW Dolinie Cierniodławów żyje taki kowal. Galvan Prastary, przywódca Zakonu Mithrilu, wykuje broń według twoich wskazówek. Jego obozowisko znajdziesz między Zul\'Gurub a Ogrzym Kopcem Mosh\'Ogg.$B$BNiech twoja determinacja i wiara przeprowadzą cię przez tę próbę. A gdybyś $gzawiódł:zawiodła;, wiedz, że twój bóg się do ciebie uśmiecha, $gśmiertelniku:śmiertelniczko;.', 'Zanieś przesyłkę dla Galvana Galvanowi Prastaremu w Dolinie Cierniodławów.', '', '', '', '', '', '', 0),
(3625, 'plPL', 'Zaczarowana azsharytowa broń spaczenia', '$N, wykucie każdej broni zajmie trochę czasu.$B$BPoza tym mocy Spaczonej klątwy możesz używać tylko raz na trzy minuty. Czas, przez jaki osłabia ona Razelikha Plugawiciela i jego sługi, bywa różny. Dlatego Spaczoną klątwę musisz uwolnić dopiero we właściwej chwili!$B$BA teraz daj mi chwilę na wykucie twojej broni, $N.$B', 'Zaczekaj, aż Galvan skończy wykuwać broń.', 'Wykuwanie broni', 'Wróć do Galvana Prastarego w Dolinie Cierniodławów.', '', '', '', '', 0),
(3626, 'plPL', 'Powrót na Jałowe Ziemie', 'Godzina odkupienia jest bliska, $N. Musisz wrócić na Jałowe Ziemie z nowo zdobytą bronią i porozmawiać z Poległym bohaterem Hordy, by poznać swój ostatni cel.$B', 'Wróć do Poległego bohatera Hordy na Rozstajach Strzaskanej Włóczni na Moczarach Smutków.', '', '', '', '', '', '', 0),
(3721, 'plPL', 'Własny OOX', '', '', '', '', '', '', '', '', 0),
(4621, 'plPL', 'Ahoj, admirale!', 'Słuchaj uważnie, morski psie... to potęga Łupieżczej Zatoki nie pozwala nam, Krwawym Żaglom, pływać, gdzie nam się podoba, i brać, co nam się należy z prawa łupu. Gdybyś $gwbił:wbiła; nóż w mistrza floty Morskiego Rogu, nigdy więcej nie wpadlibyśmy na żaden statek z Łupieżczej Zatoki. Gdybyś $gwbił:wbiła; nóż w barona Revilgaza, nigdy więcej nie stanęlibyśmy przed ich prawem.$B$BJeśli masz być honorowym admirałem wśród nas – tak, ADMIRAŁEM – wbijesz nóż w obu, jak żem rzekł. Ruszaj teraz, $gchłopcze:dziewczyno;, i wracaj, jak już zrobisz, co trza.', 'Zabij mistrza floty Morskiego Rogu i barona Revilgaza z Łupieżczej Zatoki, a następnie wróć do dowódcy floty Firallona na pokładzie „Szkarłatnego Welonu” u wybrzeży Doliny Cierniodławów.', '', 'Wróć do dowódcy floty Firallona w Dolinie Cierniodławów.', '', '', '', '', 0),
(4785, 'plPL', 'Cienka złota nić', '', '', '', '', '', '', '', '', 0),
(5148, 'plPL', 'Garbarstwo plemienne', 'Nauka garbarstwa plemiennego wymaga zrozumienia, jak pierwotna jest naprawdę natura. Wiem, że $gopanowałeś:opanowałaś; już sztukę wyrobu dzikich skórzanych pancerzy, i jestem gotów dokończyć twoje szkolenie.$B$BWiedz jednak, $N: wybierając tę ścieżkę, zgadzasz się nigdy nie uczyć garbarstwa smoczołuskiego ani garbarstwa żywiołów – można praktykować tylko jedną z tych trzech sztuk. Co więcej, przynieś mi najlepsze okazy swoich dzikich skórzanych pancerzy. Od tego zaczniemy twoją drogę do mistrzostwa.', 'Przynieś dziką skórzaną kamizelkę i dziki skórzany hełm Se\'Jibowi w Dolinie Cierniodławów.$B$BUkończenie tego zadania da ci dostęp do sztuki garbarstwa plemiennego.$B$BUkończenie tego zadania uniemożliwi ci naukę garbarstwa smoczołuskiego i garbarstwa żywiołów. Zanim to zrobisz, upewnij się, że to ścieżka, którą chcesz podążać.', '', 'Wróć do Se\'Jiba w Dolinie Cierniodławów.', '', '', '', '', 0),
(7810, 'plPL', 'Mistrz Areny', 'Bycie mistrzem areny musi oznaczać coś więcej niż to! Może pirat, który prowadzi zawody na Arenie Gurubaszów, będzie wiedział!', 'Porozmawiaj z Krótkim Johnem Mithrilem na arenie w Cierniodławach.', '', 'Zamelduj się u Krótkiego Johna Mithrila na Arenie Gurubaszów w Dolinie Cierniodławów.', '', '', '', '', 0),
(7838, 'plPL', 'Arcymistrz Areny', '', '', '', 'Wróć do Krótkiego Johna Mithrila na Arenie Gurubaszów w Dolinie Cierniodławów.', '', '', '', '', 0),
