INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(2501, 1, 0, 'plPL', 'Bah! $n, ta stopa ani drgnie!'),
(14875, 0, 0, 'plPL', 'Rozpocznijcie rytuał, moi słudzy. Musimy wygnać serce Hakkara z powrotem w pustkę!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(23, 'plPL', 'No, jestem. I jestem gotów znów dołączyć...', '', 0),
(100, 'plPL', 'Dzięki za ratunek!', '', 0),
(102, 'plPL', 'Pora na mój patrol. Zaraz wracam.', '', 0),
(103, 'plPL', 'Teraz, kiedy droga wolna...', '', 0),
(105, 'plPL', 'Długo mnie nie było... Lepiej już wrócę.', '', 0),
(106, 'plPL', 'Szeregowy Thorsen melduje powrót z patrolu. Nic nowego – na zewnątrz jest całkiem spokojnie...', '', 0),
(108, 'plPL', '', 'Bardzo dobrze. Możesz odejść, szeregowy. Odpocznij, ale nie rozleniwiaj się za bardzo. Kurzen nie da nam spokoju na zawsze.', 0),
(229, 'plPL', 'Niech cię szlag, $n! Pewnego dnia dokonam zemsty!', '', 0),
(681, 'plPL', '%s oniemiał pod wpływem klejnotu dusz!', '', 0),
(737, 'plPL', 'Gdzie, na Rubież, podziewają się te dostawy? Całymi dniami każą mi czekać!', '', 0),
(738, 'plPL', 'Głupota! Otacza mnie sama głupota!', '', 0),
(739, 'plPL', 'Orkowie są bystrzejsi od tych kurierów! Gdzie oni się, do diabła, podziewają?', '', 0),
(742, 'plPL', '%s kładzie przed sobą Oko umysłu i śpiewające kryształy...', '', 0),
(743, 'plPL', 'Wykonałem klejnot dusz Yenniku, $n...', '', 0),
(744, 'plPL', '%s próbuje otworzyć szpotawą stopę Maury\'ego...', '', 0),
(764, 'plPL', 'SMOTTS! HEJ, SMOTTS!! WYJDŹ SIĘ POBAWIĆ!', '', 0),
(765, 'plPL', '', 'Jeszcze raz dziękuję za pomoc. Niech w twoich podróżach wiatr zawsze wieje ci w plecy.', 0),
(772, 'plPL', 'OSTATNIM RAZEM TAK DOBRZE SIĘ Z TOBĄ BAWIŁEM... WYJDŹ!', '', 0),
(773, 'plPL', 'SMOTTS!', '', 0),
(774, 'plPL', 'OBIECUJĘ, ŻE TYM RAZEM NIE ZABIJĘ TWOJEJ ZAŁOGI. HA! ALE MÓJ BRAT MOŻE JĄ ZJEŚĆ!', '', 0),
(775, 'plPL', 'PRZYJDŹ NA CYPEL JANEIRO. CZEKAM NA CIEBIE, SMOTTS...', '', 0),
(776, 'plPL', 'NIE CHCESZ WALCZYĆ, SMOTTS!?', '', 0),
(777, 'plPL', 'SKOŃCZYŁY CI SIĘ STATKI DO WYSYŁANIA? GDZIE TWOJA ODWAGA?', '', 0),
(778, 'plPL', 'NIE ZOSTAWIAJ MNIE TYLKO W TOWARZYSTWIE TEGO POSĄGU. WYJDŹ SIĘ POBAWIĆ!', '', 0),
(1664, 'plPL', 'Chętnie posłucham, co ma do powiedzenia tak gniewny ork...', '', 0),
(1665, 'plPL', '%s wkłada głowę Marga do kotła.', '', 0),
(1666, 'plPL', 'Zajrzyj do kotła, $n. Marg chce przemówić...', '', 0),
(3794, 'plPL', 'Zasilanie awaryjne włączone! Inicjalizacja silnika lokomocyjnego! KO-KO!', '', 0),
(3795, 'plPL', 'Wykryto zagrożenie fizyczne! Manewr wymijający! KO-KO!', '', 0),
(3796, 'plPL', 'Zagrożenie przeanalizowane! Aktywacja planu bojowego beta! KO-KO!', '', 0),
(3797, 'plPL', 'KO-KO! Czujniki wykryły anomalię przestrzenną – niebezpieczeństwo tuż-tuż! KO-KO!', '', 0),
(3816, 'plPL', 'Systemy lotu aktywne! KO-KO! Odpalam rakiety, kurs na Łupieżczą Zatokę!', '', 0),
(3819, 'plPL', 'Zasilanie awaryjne włączone! Inicjalizacja silnika lokomocyjnego! KO-KO!', '', 0),
(3820, 'plPL', 'Systemy lotu aktywne! KO-KO! Odpalam rakiety, kurs na Łupieżczą Zatokę!', '', 0),
(3821, 'plPL', 'KO-KO! Czujniki wykryły anomalię przestrzenną – niebezpieczeństwo tuż-tuż! KO-KO!', '', 0),
(3822, 'plPL', 'KO-KO! Czujniki wykryły anomalię przestrzenną – niebezpieczeństwo tuż-tuż! KO-KO!', '', 0),
(3823, 'plPL', 'Systemy lotu aktywne! KO-KO! Odpalam rakiety, kurs na Łupieżczą Zatokę!', '', 0),
(3824, 'plPL', 'Zasilanie awaryjne włączone! Inicjalizacja silnika lokomocyjnego! KO-KO!', '', 0),
(4182, 'plPL', 'Sul\'thraze... Pierwszy raz usłyszałem to słowo, gdy byłem mniej więcej w twoim wieku. Nic mi wtedy nie mówiło, tak jak tobie nic nie mówi teraz. Dopiero gdy banda wojenna trolli z Zul\'Farrak spustoszyła tę ziemię, zrozumiałem... i zacząłem się bać.$B$BWielu powie ci, że Rozszczepione Ostrze Męki nie istnieje. Że to mit, plotka puszczona w obieg, by straszyć dzieci. Ale uwierz mi, ono istnieje.$B$B<Trenton traci wątek i przesuwa dłonią po poszarpanej bliźnie na twarzy.>', '', 0),
(4183, 'plPL', 'Opowiedz mi więcej, Trentonie.', 'Opowiedz mi więcej, Trentonie.', 0),
(4184, 'plPL', 'Rozdzielone na dwoje, by stworzyć jedno. Bliźniacze ostrza są związane z Zul\'Farrak.$B$BSul\'thraze odrodzi się, gdy bliźniaki zostaną odnalezione.', '', 0),
(4228, 'plPL', '$GUwolniłeś:Uwolniłaś; Kiritha od cierpienia? Nie do pomyślenia – a teraz Trebor przysłał cię tutaj po wiedzę o demonach i ich sługach?$B$B<Loramus się śmieje.>$B$BDziękuj losowi, że tajemne bóle wreszcie ustąpiły.', '', 0),
(4229, 'plPL', 'Czy ich widzisz, $gśmiertelniku:śmiertelniczko;? Nie... Nie sądzę, by to było możliwe. Masz wzrok, a nie widzisz – to twój dar i twoje przekleństwo.', '', 0),
(4230, 'plPL', 'Witaj, Loramusie. Przynoszę wieści z Jałowych Ziem.', 'Witaj, Loramusie. Przynoszę wieści z Jałowych Ziem.', 0),
(4245, 'plPL', 'Pomożesz?', 'Pomożesz?', 0),
(4246, 'plPL', 'W epoce wojny Razelikh Plugawiciel był najstraszliwszym z poruczników lorda Kazzaka. Gdy Legion został pokonany, a Kazzak zepchnięty z powrotem do Skażonej Blizny, pan powierzył Razelikhowi zadanie zabezpieczenia Jałowych Ziem.$B$BPodczas gdy Przymierze toczyło z Hordą drobne potyczki o terytoria poza Jałowymi Ziemiami, Razelikh jednoczył odłamy Rady Cieni i brutalne ogry z klanu Upiornych Maczug.', '', 0),
(4247, 'plPL', 'Proszę, mów dalej.', 'Proszę, mów dalej.', 0),
(4248, 'plPL', 'Na nieszczęście to mądrość Thralla ostatecznie przypieczętowała więź między władcą demonów a jego sługami. To oddział Trebora stał się katalizatorem, który zjednoczył władcę demonów, odłamy Cienioprzysięgłych i ogry. Pokusa niemal nieograniczonej mocy i nieśmiertelnych oddziałów szturmowych dla każdego z przywódców przypieczętowała ten pakt krwią.\n', '', 0),
(4249, 'plPL', 'Nie rozumiem.', 'Nie rozumiem.', 0),
(4250, 'plPL', 'Sevine, Allistarj i Grol nie zdawali sobie sprawy, że tak jak ich słudzy zostali przywiązani do tej ziemi, tak samo stanie się z nimi... Widzisz, ceną za ich własną nieśmiertelność było także uwięzienie i wieczna służba pod rozkazami Razelikha. Okrutny spryt Razelikha znów zatriumfował.\n', '', 0),
(4251, 'plPL', 'Rzeczywiście.\n', 'Rzeczywiście.\n', 0),
(4253, 'plPL', 'Ich umysły są teraz skażone. Tak, jeszcze bardziej niż przedtem. Żyją tylko po to, by służyć Razelikhowi i go chronić. Fragmenty amuletu, które każde z nich posiada, są kluczem do przyzwania władcy demonów. Nie rozumiesz jednak, że żadnego z nich nie da się zranić zwykłymi sposobami.', '', 0),
(4254, 'plPL', 'Zrobię to z twoją pomocą albo bez niej, Loramusie.\n', 'Zrobię to z twoją pomocą albo bez niej, Loramusie.\n', 0),
(4255, 'plPL', 'W takim razie załóżmy, że podejmiesz się długiego i żmudnego zadania stworzenia zguby, która przełamie demoniczne osłony nałożone na triadę. Jaki byłby twój następny krok? Stawić czoło Plugawicielowi w jego leżu?$B$B<Loramus się śmieje.>\n', '', 0),
(4256, 'plPL', 'Tak.\n', 'Tak.\n', 0),
(4257, 'plPL', 'Chcę usłyszeć twoją historię.', 'Chcę usłyszeć twoją historię.', 0),
(4365, 'plPL', 'Słuchajcie, mieszkańcy Tanaris! Niech wszyscy wiedzą, że $n jest czcigodnym członkiem Zakonu Mithrilu. $GKowal:Kowalka; honoru, oddania i nieskończonej cierpliwości. Niech żyje $n! Hip, hip, hurra!', '', 0),
(4563, 'plPL', 'Z moich badań wynika, że pokonanie awatara boga Hakkara osłabiło go. Jednak większość jego siły przetrwała i czai się na dalekim krańcu Otchłani.$B$BRaz już $gpokonałeś:pokonałaś; jego awatara, $n. Może jeśli pokonasz go ponownie, zdołasz jeszcze bardziej osłabić boga, byśmy pewnego dnia mogli stawić czoło jemu samemu.$B$BPrzygotowałem zaklęcie, dzięki któremu możesz ponownie przyzwać awatara Hakkara w Sanktuarium Upadłego Boga. Czy chcesz znów się z nim zmierzyć?', '', 0),
(4565, 'plPL', 'Witaj, $N. Choć czas i trunki przytępiły moje zewnętrzne zmysły, moje wewnętrzne oczy wciąż widzą wyraźnie.', '', 0),
(4567, 'plPL', 'Tak. Daj mi zaklęcie przyzwania awatara.', 'Tak. Daj mi zaklęcie przyzwania awatara.', 0),
(4576, 'plPL', 'Musisz otworzyć zestaw tropiciela ogarów spaczenia i przeczytać instrukcję. Przyzwij bestię, gdy będziesz w pobliżu półwyspu klifowych olbrzymów, na południe stąd.', '', 0),
(4960, 'plPL', 'Muszę przyznać, że w Łupieżczej Zatoce podają najlepszą zupę z małży na całych Południowych Morzach. Och, kuchnia cię nie interesuje, co? W takim razie witam cię przy nabrzeżu „Panieńskiego Kaprysu”, najwspanialszego statku pasażerskiego kursującego między Wschodnimi Królestwami a Kalimdorem. Niedługo wraca, by znów popłynąć do Zapadki, więc rozgość się, zanim przypłynie.', 'Muszę przyznać, że w Łupieżczej Zatoce podają najlepszą zupę z małży na całych Południowych Morzach. Och, kuchnia cię nie interesuje, co? W takim razie witam cię przy nabrzeżu „Panieńskiego Kaprysu”, najwspanialszego statku pasażerskiego kursującego między Wschodnimi Królestwami a Kalimdorem. Niedługo wraca, by znów popłynąć do Zapadki, więc rozgość się, zanim przypłynie.', 0),
(5472, 'plPL', 'Nie mam pojęcia, czemu ktoś chciałby opuszczać te słoneczne brzegi i krystalicznie błękitne wody. Tu jest jak w raju. Tylko nie mów tego mojemu bratu – Zapetta i tak jest już dość zgorzkniały, bo utknął tam w Tirisfal na całe dnie. Ten sterowiec zatrzymuje się w Orgrimmarze, więc nie musisz się martwić jego marudzeniem. Ale jeśli w najbliższym czasie zawitasz do Tirisfal, posłuchaj mojej rady i nie zaczynaj z nim rozmowy.', 'Nie mam pojęcia, czemu ktoś chciałby opuszczać te słoneczne brzegi i krystalicznie błękitne wody. Tu jest jak w raju. Tylko nie mów tego mojemu bratu – Zapetta i tak jest już dość zgorzkniały, bo utknął tam w Tirisfal na całe dnie. Ten sterowiec zatrzymuje się w Orgrimmarze, więc nie musisz się martwić jego marudzeniem. Ale jeśli w najbliższym czasie zawitasz do Tirisfal, posłuchaj mojej rady i nie zaczynaj z nim rozmowy.', 0),
(5522, 'plPL', 'Niech żyje $n – admirał floty bukanierów Krwawych Żagli!', '', 0),
(5523, 'plPL', 'Hip, hip... arrrrr...', '', 0),
(5820, 'plPL', 'No? Pewnie, że znam się na kowalstwie. Co, myślisz, że tylko krasnoludy są warte tyle złota, ile ważą ich kowadła? Dobra, jak chcesz. Idź poszukaj krasnoluda, niech on ci pomoże!', '', 0),
(6295, 'plPL', 'Jak leci, mon!', '', 0),
(7377, 'plPL', 'Wsuń szefowi do ręki parę monet i patrz, co z tego masz. Kocham swoją pracę. Chociaż gdybym znalazł sposób, żeby przenieśli tę małą petardę Snurk do tego portu... nie wyobrażam sobie nic lepszego. Ale założę się, że nie przychodzisz tu w sprawie moich metod pracy. Szukasz sterowca do Podmiasta, zgadłem? No to świetnie, bo cumuje tuż za mną. Aha, i jeśli zobaczysz Snurk, szepnij jej o mnie dobre słowo, dobra?', 'Wsuń szefowi do ręki parę monet i patrz, co z tego masz. Kocham swoją pracę. Chociaż gdybym znalazł sposób, żeby przenieśli tę małą petardę Snurk do tego portu... nie wyobrażam sobie nic lepszego. Ale założę się, że nie przychodzisz tu w sprawie moich metod pracy. Szukasz sterowca do Podmiasta, zgadłem? No to świetnie, bo cumuje tuż za mną. Aha, i jeśli zobaczysz Snurk, szepnij jej o mnie dobre słowo, dobra?', 0),
(7624, 'plPL', 'To niebezpieczne miejsce, $n. Uważaj na siebie.', '', 0),
(7653, 'plPL', 'Nie marnuj mojego czasu.', 'Nie marnuj mojego czasu.', 0),
(7738, 'plPL', 'Glyx i ja mamy układ: on mnie zaopatruje, a ja robię z niego bogacza. Serio! Tyle, ile ten pirat bierze ode mnie za marny woreczek pogniecionej królewskiej krwi... dorosły goblin mógłby się rozpłakać.', '', 0),
(8014, 'plPL', 'Na razie mamy na tym kontynencie tylko mały przyczółek, ale ludzie nie będą nas odpierać wiecznie. Wtedy zapłacą za to, że nas zniewolili. Za tę zdradę powyrywamy im te kłamliwe jęzory.', '', 0),
(8104, 'plPL', 'Najszybsze gryfy po tej stronie Orlego Gniazda. Chcesz się przelecieć?', '', 0),
(8105, 'plPL', 'Jasne! Lećmy.', 'Jasne! Lećmy.', 0),
(8152, 'plPL', 'Mówią, że jeden szew w porę oszczędza... ile, jedenaście? Ech, nie pamiętam. I tak głupie powiedzenie.', '', 0),
(9017, 'plPL', 'Mistrza Nesingwary\'ego czeka wielkie polowanie. Pomaganie mu w przygotowaniach do dnia w dżungli jest dla mnie o wiele przyjemniejsze niż szykowanie go do walki. Choć przyznam, że tęsknię za niektórymi chwalebnymi chwilami na polu bitwy.', '', 0),
(9018, 'plPL', 'Barnilu, chyba $gzapodziałem:zapodziałam; rozdział I.', 'Barnilu, chyba $gzapodziałem:zapodziałam; rozdział I.', 0),
(9019, 'plPL', 'Barnilu, chyba $gzapodziałem:zapodziałam; rozdział II.', 'Barnilu, chyba $gzapodziałem:zapodziałam; rozdział II.', 0),
(9020, 'plPL', 'Barnilu, chyba $gzapodziałem:zapodziałam; rozdział III.', 'Barnilu, chyba $gzapodziałem:zapodziałam; rozdział III.', 0),
(9021, 'plPL', 'Barnilu, chyba $gzapodziałem:zapodziałam; rozdział IV.', 'Barnilu, chyba $gzapodziałem:zapodziałam; rozdział IV.', 0),
(9022, 'plPL', 'Widzę, że $gzgubiłeś:zgubiłaś; rozdział, nad którego skompletowaniem tak się $gnapracowałeś:napracowałaś;, $n. Cóż, $gzostawiłeś:zostawiłaś; go właśnie tutaj!', '', 0),
(9730, 'plPL', 'Arrr, moje zuchy! Mam tu trochę zbędnego skarbu, co go rozdaję na Arenie Gurubaszów! Wystarczy, że otworzycie skrzynię, którą zostawię na arenie!', '', 0),
(9731, 'plPL', 'Niech rozpocznie się rozlew krwi!', '', 0),
(9795, 'plPL', 'Arr! Nic tak nie cieszy oka jak ludziska walczące na arenie na śmierć i życie. Jak się zjawisz we właściwym czasie, może trafisz między nich!', '', 0),
(10268, 'plPL', 'Jeśli przybywasz, by ocalić świat, to jesteś we właściwym miejscu. Ten bez twarzy – Bóg Krwi, Hakkar – powrócił do naszego świata!', '', 0),
(10379, 'plPL', 'Jestem Jin\'rokh Łamacz, wysłannik Mugamby – Pięści Rastakana!$B$BZajmuję się sprawami wojowników i pogan.', '', 0),
(10381, 'plPL', 'Jestem Al\'tabim Wszechwidzący – wysłannik króla Rastakana.$B$BZajmuję się sprawami kapłanów, magów i czarnoksiężników.', '', 0),
(10426, 'plPL', '', 'A czego się spodziewać, mon?$B$BMaywiki handlować tylko z druidami i szamanami.', 0),
(10433, 'plPL', 'Choć jestem niewidomy, mam wizję.$B$BZajmuję się głównie łowcami i łotrzykami.', '', 0),
(10440, 'plPL', 'Witaj, $gposzukiwaczu:poszukiwaczko; przygód. Jestem Rin\'wosho, kupiec z Zuldazaru. Przybywam z Południowych Mórz i przywożę wiele egzotycznych towarów i przedmiotów z mojej ojczyzny.$B$BByć może, jeśli udowodnisz swoją wartość mojemu plemieniu, pohandluję z tobą. A jeśli masz żetony honoru mojego plemienia, być może pohandlujemy jeszcze więcej.', '', 0),
(10456, 'plPL', 'To prawda, $n. Koła zagłady obracają się teraz nieuchronnie ku prawdziwemu powrotowi Hakkara!', '', 0),
(10457, 'plPL', 'Krew i dusze dla Hakkara! HAHAHAH!', '', 0),
(10476, 'plPL', 'Witaj, $N. Jestem Exzhal, sługa Rastakana.', '', 0),
(10493, 'plPL', '*Wrrr* *BRZDĘK*\nPolecono mi przyjmować rzadkie ryby wysokiej jakości i wydawać w zamian cenne akcesoria wędkarskie Nata Pagle\'a. Poproszę o rybę.\n*ŁUP* *Bzzz*\n', '', 0),
(10537, 'plPL', 'Niech żyje $n, $gpogromca:pogromczyni; Hakkara i $gbohater:bohaterka; Azeroth!', '', 0),
(10571, 'plPL', '', 'Mistrz wędkarski Okoniowa Przynęta kazał zarybić tutejsze wody dorodnymi smakorybami, żeby urządzić swój turniej.\nGdy już wyłoni zwycięzców, dam ci srebro za każde pięć smakorybów, które mi przyniesiesz!', 0),
(10600, 'plPL', 'Mamy już wszystkich zwycięzców dzisiejszych zawodów, ale Jang chętnie kupi każdego smakoryba, którego uda ci się złowić!\nSwoje wędkarskie umiejętności zawsze możesz pokazać w następną niedzielę!', '', 0),
(10608, 'plPL', 'Turniej wędkarski czas ZACZĄĆ!', '', 0),
(10609, 'plPL', 'I smakoryby odpłynęły na cały tydzień! Zostanę tu jeszcze godzinę, żeby każdy zdążył oddać swoje ryby!', '', 0),
(10610, 'plPL', 'Mamy zwycięzcę! $n zajmuje PIERWSZE MIEJSCE w turnieju!', '', 0),
(10612, 'plPL', 'Bóg Krwi, Duszożerca, został pokonany! Nie grozi nam już niebezpieczeństwo!', '', 0),
(10616, 'plPL', 'My, trolle Zandalarów, przybyliśmy tu z odległych wysp, bo nie możemy lekceważyć zagrożenia, przed którym stoi teraz nasz świat.$B$BPrzywódca naszej wyprawy, Molthor, przywiódł nas na Wyspę Yojamba u północnych wybrzeży Cierniodławów i nawet teraz werbuje dzielnych bohaterów, którzy zapuszczą się do starożytnego miasta trolli... Zul\'Gurub.', '', 0),
(10618, 'plPL', 'My, trolle Zandalarów, przybyliśmy tu z odległych wysp, bo nie możemy lekceważyć zagrożenia, przed którym stoi teraz nasz świat.', '', 0),
(11656, 'plPL', 'Gdzie jest Nestor Gwiezdna Polana?', 'Gdzie jest Nestor Gwiezdna Polana?', 0),
(11657, 'plPL', 'Nestora Gwiezdną Polanę znajdziesz przed bramami Zul\'Gurub w Dolinie Cierniodławów.', 'Nestora Gwiezdną Polanę znajdziesz przed bramami Zul\'Gurub w Dolinie Cierniodławów.', 0),
(11932, 'plPL', 'To się nazywa chybiona inwestycja!$B$BMroczna księga zaklęć lorda Valthalaka poszła na czarnym rynku za niezłą sumkę. Szkoda tylko, że niezbyt mu się spodobało, że ukradziono mu dobytek. Ten śmierdziel dopadł nas, choć od miesięcy nie żył!', '', 0),
(12031, 'plPL', 'Proszę, mów dalej.', 'Proszę, mów dalej.', 0),
(12341, 'plPL', 'Z drogi, parszywy psie! Revilgaz oszczędził mi szubienicy, ale moja kara może być niemal równie straszna.', 'Z drogi, parszywy psie! Revilgaz oszczędził mi szubienicy, ale moja kara może być niemal równie straszna.', 0),
(12345, 'plPL', 'W czym mogę pomóc, $n? Tylko szybko, nie mam całego dnia!', '', 0),
